/**
 * RUS-5940 — page-local shared recipes for the Account Center.
 *
 * Page-level shared style module (sanctioned pattern, component-map living
 * addendum: `planning-v2/surveyShared.tsx` RUS-5936 and `performance-v2/styles.ts`
 * RUS-5920 rev-5 precedents). The Account Center is a non-designed page with no
 * Figma frame, so its repeated recipes have no Kit home and live here once
 * instead of being re-inlined across five tab files.
 *
 * Rules this module follows (component-map, RUS-5937 rev 2 — review findings
 * are filed against violations):
 *   - every entry COMPOSES a `v2Typography` role and adds only a modifier;
 *     a raw `fontSize`/`fontWeight`/`lineHeight` literal here is a defect,
 *   - no new global tokens, no colour literal, no `${t.token}NN` alpha
 *     construction — the semantic fill families below ARE the sanctioned
 *     replacements for the alpha pairs this page used before the migration,
 *   - numeric `sx` values are MUI theme multipliers, so every token-derived
 *     dimension is emitted as a `px` STRING (`${t.space[16]}px`). The bare
 *     `p: t.space[16]` form would multiply by the theme spacing unit — the
 *     RUS-5846/RUS-5897 "​px-string" footgun.
 */
import { V2Tokens, v2Typography } from '../v2';

/** Tabular numerals — the E4 replacement for the retired JetBrains Mono face.
 *  Applied to every value column that previously opted into a mono family. */
export const tnum = { fontFeatureSettings: "'tnum' 1" } as const;

/** Analytical section eyebrow — the shared `tableHeader` role, muted by the
 *  caller's slot (component-map: eyebrows are NOT a local 11px/600 recipe). */
export const sectionLabel = (t: V2Tokens) => ({ ...v2Typography.tableHeader, color: t.textMuted });

/** Row/setting title — 13/18 Medium (cardTitle role). */
export const rowLabel = (t: V2Tokens) => ({ ...v2Typography.cardTitle, color: t.text });

/** Row/setting supporting copy — 11/16 Regular. */
export const rowDesc = (t: V2Tokens) => ({ ...v2Typography.bodySmall, color: t.textMuted });

/** Body copy — 12/18 Regular on the secondary text tone. */
export const bodyText = (t: V2Tokens) => ({ ...v2Typography.body, color: t.textSub });

/** Body copy, strong — 12/18 Medium, primary text tone. */
export const bodyStrong = (t: V2Tokens) => ({ ...v2Typography.bodyMedium, color: t.text });

/**
 * In-card panel surface — the ONE bordered grouping used inside a section
 * card. Deliberately a single recipe: the pre-migration page re-inlined
 * `p + radius + cardNested + borderSubtle` in more than twenty places with
 * drifting radii (6/8/9/10/12/14/16/20px).
 */
export const panelSx = (t: V2Tokens) => ({
  p: `${t.space[16]}px`,
  borderRadius: `${t.radius.card}px`,
  background: t.cardNested,
  border: `1px solid ${t.borderSubtle}`,
});

/** Hairline-separated row inside a section card — the container-free idiom
 *  used for settings rows (no nested box that only adds padding). */
export const dividerRowSx = (t: V2Tokens) => ({
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'space-between',
  gap: `${t.space[16]}px`,
  paddingBlock: `${t.space[12]}px`,
  borderBottom: `1px solid ${t.borderSubtle}`,
  '&:last-of-type': { borderBottom: 'none' },
});

/**
 * Severity strip — the sanctioned fill/border/text triplet from the design
 * file's `alert` semantic family, replacing the `${t.negative}10` /
 * `${t.negative}30` alpha pairs the page composed by hand. `info` is the TEAL
 * informational family, never the C1 `warnLow` Tailwind blue.
 */
export type StripTone = 'error' | 'warning' | 'success' | 'info';

const STRIP_TOKENS = {
  error: (t: V2Tokens) => [t.alert.errorBackground, t.alert.errorBorder, t.alert.errorText],
  warning: (t: V2Tokens) => [t.alert.warningBackground, t.alert.warningBorder, t.alert.warningText],
  success: (t: V2Tokens) => [t.alert.successBackground, t.alert.successBorder, t.alert.successText],
  info: (t: V2Tokens) => [t.alert.infoBackground, t.alert.infoBorder, t.alert.infoText],
} as const;

export const stripSx = (t: V2Tokens, tone: StripTone) => {
  const [background, border, text] = STRIP_TOKENS[tone](t);
  return {
    p: `${t.space[12]}px ${t.space[16]}px`,
    borderRadius: `${t.radius.control}px`,
    background,
    border: `1px solid ${border}`,
    color: text,
  };
};

/** The strip's text tone, for callers that need it outside `stripSx`. */
export const stripText = (t: V2Tokens, tone: StripTone) => STRIP_TOKENS[tone](t)[2];

/**
 * MUI TextField recipe (A10: no Figma input design exists — behaviour stays
 * MUI, only the geometry is token-restyled to match the Kit's own `V2Input`).
 */
export const fieldSx = (t: V2Tokens) => ({
  '& .MuiOutlinedInput-root': {
    background: t.cardNested,
    borderRadius: `${t.radius.control}px`,
    '& fieldset': { borderColor: t.border },
    '&:hover fieldset': { borderColor: t.borderHover },
    '&.Mui-focused fieldset': { borderColor: t.accent },
  },
  '& .MuiInputBase-input': { ...v2Typography.body, color: t.text },
  '& .MuiInputBase-input::placeholder': { color: t.textMuted, opacity: 1 },
});

/** MUI Select recipe — same geometry as `fieldSx`, plus the portaled menu. */
export const selectSx = (t: V2Tokens) => ({
  background: t.cardNested,
  borderRadius: `${t.radius.control}px`,
  '& .MuiOutlinedInput-notchedOutline': { borderColor: t.border },
  '&:hover .MuiOutlinedInput-notchedOutline': { borderColor: t.borderHover },
  '&.Mui-focused .MuiOutlinedInput-notchedOutline': { borderColor: t.accent },
  '& .MuiSelect-select': { ...v2Typography.body, color: t.text },
});

/** Dropdown paper for `Select`/`Autocomplete` — replaces the six copies of
 *  the cardElevated + radius + MenuItem recipe the page carried, and drops
 *  the mono font family from every option row. */
export const menuPaperSx = (t: V2Tokens) => ({
  background: t.cardElevated,
  border: `1px solid ${t.border}`,
  borderRadius: `${t.radius.card}px`,
  boxShadow: t.shadow,
  mt: 0.5,
  '& .MuiMenuItem-root': {
    ...v2Typography.body,
    color: t.text,
    '&:hover': { background: t.accentDim },
    '&.Mui-selected': { background: t.accentDim, color: t.accent },
    '&.Mui-selected:hover': { background: t.accentDim },
  },
  '& .MuiAutocomplete-option': {
    ...v2Typography.body,
    color: t.text,
    '&:hover': { background: t.accentDim },
    '&[aria-selected=true]': { background: t.accentDim, color: t.accent },
  },
  '& .MuiAutocomplete-groupLabel': {
    ...v2Typography.caption,
    color: t.textMuted,
    textTransform: 'uppercase',
    background: t.cardElevated,
    top: 0,
  },
});

/** MUI Switch binding — the shared accent treatment so the two hand-rolled
 *  affordances this page carried (a click-only Box toggle) are replaced by a
 *  real form control with keyboard semantics. */
export const switchSx = (t: V2Tokens) => ({
  '& .MuiSwitch-switchBase.Mui-checked': { color: t.accent },
  '& .MuiSwitch-switchBase.Mui-checked + .MuiSwitch-track': { backgroundColor: t.accent },
});

/** Inline text-button (link-shaped action) — token tone only. */
export const inlineLinkSx = (t: V2Tokens) => ({
  background: 'none',
  border: 'none',
  padding: 0,
  cursor: 'pointer',
  fontFamily: 'inherit',
  color: t.textMuted,
  '&:hover': { color: t.text },
});

