1	import { useState, useEffect, useRef } from 'react';
2	import { Box, Typography, Collapse } from '@mui/material';
3	import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
4	import {
5	  Laptop,
6	  Smartphone,
7	  Computer,
8	  Mail,
9	  Public,
10	  ExpandMore,
11	  Info,
12	} from '@mui/icons-material';
13	import { useV2Tokens, v2Typography } from '../../v2/tokens';
14	import { V2SectionCard } from '../../v2/V2SectionCard';
15	import { V2Reveal } from '../../v2/V2Reveal';
16	import { V2StatusBadge } from '../../v2/V2StatusBadge';
17	import { V2Button } from '../../v2/V2Button';
18	import { V2Modal } from '../../v2/V2Modal';
19	import { V2Callout } from '../../v2/V2Callout';
20	import {
21	  listSessions,
22	  revokeSession,
23	  logoutAllSessions,
24	  listConnectedAccounts,
25	  linkGoogle,
26	  unlinkGoogle,
27	} from '../../../lib/endpoints';
28	import { useAuth } from '../../../contexts/AuthContext';
29	import type { SessionInfo } from '../../../types';
30	import { panelSx, sectionLabel, tnum, bodyText } from '../styles';
31	
32	import { config } from '../../../config';
33	
34	const GOOGLE_CLIENT_ID = config.GOOGLE_CLIENT_ID;
35	
36	export function SecurityTab() {
37	  const t = useV2Tokens();
38	  const queryClient = useQueryClient();
39	  const { user } = useAuth();
40	  const [expandedSessions, setExpandedSessions] = useState<Set<string>>(new Set());
41	  const [confirmAction, setConfirmAction] = useState<{ type: 'logout-all' | 'sign-out' | 'disconnect-google'; sessionId?: string } | null>(null);
42	  const [googleConnecting, setGoogleConnecting] = useState(false);
43	  const [googleError, setGoogleError] = useState('');
44	  const gsiReady = useRef(false);
45	
46	  useEffect(() => {
47	    if (!GOOGLE_CLIENT_ID) return;
48	    if ((window as any).google) { gsiReady.current = true; return; }
49	    const script = document.createElement('script');
50	    script.src = 'https://accounts.google.com/gsi/client';
51	    script.async = true;
52	    script.onload = () => { gsiReady.current = true; };
53	    document.head.appendChild(script);
54	  }, []);
55	
56	  const { data: sessions = [], refetch: refetchSessions } = useQuery({
57	    queryKey: ['sessions'],
58	    queryFn: listSessions,
59	  });
60	
61	  const { data: connectedAccounts = [], refetch: refetchConnectedAccounts } = useQuery({
62	    queryKey: ['connectedAccounts', user?.id],
63	    queryFn: listConnectedAccounts,
64	    enabled: !!user?.id,
65	  });
66	
67	  const revokeMutation = useMutation({
68	    mutationFn: revokeSession,
69	    onSuccess: () => {
70	      queryClient.invalidateQueries({ queryKey: ['sessions'] });
71	    },
72	  });
73	
74	  const logoutAllMutation = useMutation({
75	    mutationFn: logoutAllSessions,
76	    onSuccess: () => {
77	      queryClient.invalidateQueries({ queryKey: ['sessions'] });
78	    },
79	  });
80	
81	  const unlinkGoogleMutation = useMutation({
82	    mutationFn: unlinkGoogle,
83	    onSuccess: () => {
84	      queryClient.invalidateQueries({ queryKey: ['connectedAccounts'] });
85	    },
86	  });
87	
88	  const toggleSessionDetails = (sessionId: string) => {
89	    setExpandedSessions((prev) => {
90	      const next = new Set(prev);
91	      if (next.has(sessionId)) {
92	        next.delete(sessionId);
93	      } else {
94	        next.add(sessionId);
95	      }
96	      return next;
97	    });
98	  };
99	
100	  const parseDeviceName = (userAgent: string | null): string => {
101	    if (!userAgent) return 'Unknown Device';
102	    if (userAgent.includes('iPhone') || userAgent.includes('iPad')) return 'iPhone';
103	    if (userAgent.includes('Android')) return 'Android Phone';
104	    if (userAgent.includes('Mac')) return 'MacBook';
105	    if (userAgent.includes('Windows')) return 'Windows PC';
106	    if (userAgent.includes('Linux')) return 'Linux Desktop';
107	    return 'Web Browser';
108	  };
109	
110	  const getDeviceIcon = (userAgent: string | null) => {
111	    if (!userAgent) return <Computer sx={{ fontSize: 22, color: t.textSub }} />;
112	    if (userAgent.includes('iPhone') || userAgent.includes('iPad') || userAgent.includes('Android')) {
113	      return <Smartphone sx={{ fontSize: 22, color: t.textSub }} />;
114	    }
115	    return <Laptop sx={{ fontSize: 22, color: t.textSub }} />;
116	  };
117	
118	  const formatLastActive = (lastUsedAt: string | null): string => {
119	    if (!lastUsedAt) return 'Never';
120	    const date = new Date(lastUsedAt);
121	    const now = new Date();
122	    const diffMs = now.getTime() - date.getTime();
123	    const diffMins = Math.floor(diffMs / 60000);
124	    if (diffMins < 1) return 'Just now';
125	    if (diffMins < 60) return `${diffMins}m ago`;
126	    const diffHours = Math.floor(diffMins / 60);
127	    if (diffHours < 24) return `${diffHours}h ago`;
128	    const diffDays = Math.floor(diffHours / 24);
129	    if (diffDays === 1) return 'Yesterday';
130	    if (diffDays < 7) return `${diffDays}d ago`;
131	    return date.toLocaleDateString();
132	  };
133	
134	  const sortedSessions = [...sessions].sort((a, b) => {
135	    const aTime = a.last_used_at ? new Date(a.last_used_at).getTime() : 0;
136	    const bTime = b.last_used_at ? new Date(b.last_used_at).getTime() : 0;
137	    return bTime - aTime;
138	  });
139	  const currentSessionId = sortedSessions[0]?.id || null;
140	  const googleAccount = connectedAccounts.find((acc) => acc.provider === 'google');
141	
142	  const confirmTitle =
143	    confirmAction?.type === 'logout-all' ? 'Sign out other devices'
144	    : confirmAction?.type === 'sign-out' ? 'Sign out device'
145	    : confirmAction?.type === 'disconnect-google' ? 'Disconnect Google'
146	    : '';
147	
148	  const confirmBody =
149	    confirmAction?.type === 'logout-all' ? 'This will sign out all other sessions. You will remain signed in on this device.'
150	    : confirmAction?.type === 'sign-out' ? 'This will end the session on that device. They will need to sign in again.'
151	    : confirmAction?.type === 'disconnect-google' ? 'This will remove Google as a sign-in method. You can reconnect later.'
152	    : '';
153	
154	  const handleConfirm = () => {
155	    if (confirmAction?.type === 'logout-all') {
156	      logoutAllMutation.mutate();
157	    } else if (confirmAction?.type === 'sign-out' && confirmAction.sessionId) {
158	      revokeMutation.mutate(confirmAction.sessionId);
159	    } else if (confirmAction?.type === 'disconnect-google') {
160	      unlinkGoogleMutation.mutate();
161	    }
162	    setConfirmAction(null);
163	  };
164	
165	  return (
166	    <Box sx={{ display: 'flex', flexDirection: 'column', gap: `${t.space[24]}px` }}>
167	      {/* Section 1: Sign-in Methods (moved above sessions) */}
168	      <V2Reveal delay={0}>
169	        <V2SectionCard t={t} title="Sign-in Methods" subtitle="Connected authentication methods">
170	          <Box sx={{ display: 'flex', flexDirection: 'column', gap: `${t.space[12]}px` }}>
171	            {/* Email & Password */}
172	            <Box
173	              sx={{
174	                ...panelSx(t),
175	                display: 'flex',
176	                alignItems: 'center',
177	                justifyContent: 'space-between',
178	                flexWrap: 'wrap',
179	                gap: `${t.space[16]}px`,
180	              }}
181	            >
182	              <Box sx={{ display: 'flex', alignItems: 'center', gap: `${t.space[16]}px` }}>
183	                <Mail sx={{ fontSize: 22, color: t.accent }} />
184	                <Box>
185	                  <Typography sx={{ ...v2Typography.sectionTitle, color: t.text, mb: `${t.space[4]}px` }}>
186	                    Email &amp; password
187	                  </Typography>
188	                  <Typography sx={{ ...v2Typography.body, color: t.textMuted }}>
189	                    {user?.email}
190	                  </Typography>
191	                </Box>
192	              </Box>
193	              <V2StatusBadge t={t} severity="positive" label="Active" />
194	            </Box>
195	
196	            {/* Google */}
197	            <Box
198	              sx={{
199	                ...panelSx(t),
200	                display: 'flex',
201	                alignItems: 'center',
202	                justifyContent: 'space-between',
203	                flexWrap: 'wrap',
204	                gap: `${t.space[16]}px`,
205	              }}
206	            >
207	              <Box sx={{ display: 'flex', alignItems: 'center', gap: `${t.space[16]}px` }}>
208	                <Public sx={{ fontSize: 22, color: googleAccount ? t.accent : t.textMuted }} />
209	                <Box>
210	                  <Typography sx={{ ...v2Typography.sectionTitle, color: t.text, mb: `${t.space[4]}px` }}>
211	                    Google
212	                  </Typography>
213	                  <Typography sx={{ ...v2Typography.body, color: t.textMuted }}>
214	                    {googleAccount
215	                      ? googleAccount.email || 'Connected'
216	                      : 'Not connected'}
217	                  </Typography>
218	                </Box>
219	              </Box>
220	              {googleAccount ? (
221	                <V2Button
222	                  t={t}
223	                  variant="secondary"
224	                  onClick={() => setConfirmAction({ type: 'disconnect-google' })}
225	                >
226	                  Disconnect
227	                </V2Button>
228	              ) : GOOGLE_CLIENT_ID ? (
229	                <Box sx={{ display: 'flex', alignItems: 'center', gap: `${t.space[8]}px` }}>
230	                  {googleError && (
231	                    <Typography sx={{ ...v2Typography.bodySmall, color: t.alert.warningText }}>{googleError}</Typography>
232	                  )}
233	                  <V2Button
234	                    t={t}
235	                    variant="secondary"
236	                    loading={googleConnecting}
237	                    onClick={() => {
238	                      if (!gsiReady.current || !GOOGLE_CLIENT_ID) return;
239	                      setGoogleError('');
240	                      setGoogleConnecting(true);
241	                      const google = (window as any).google;
242	                      google.accounts.id.initialize({
243	                        client_id: GOOGLE_CLIENT_ID,
244	                        callback: async (resp: { credential: string }) => {
245	                          try {
246	                            await linkGoogle(resp.credential);
247	                            refetchConnectedAccounts();
248	                          } catch {
249	                            setGoogleError('Failed to link Google account');
250	                          } finally {
251	                            setGoogleConnecting(false);
252	                          }
253	                        },
254	                      });
255	                      google.accounts.id.prompt();
256	                    }}
257	                  >
258	                    {googleConnecting ? 'Connecting...' : 'Connect'}
259	                  </V2Button>
260	                </Box>
261	              ) : (
262	                <Typography sx={{ ...v2Typography.bodySmall, color: t.textMuted }}>Not configured</Typography>
263	              )}
264	            </Box>
265	          </Box>
266	        </V2SectionCard>
267	      </V2Reveal>
268	
269	      {/* Section 2: Active Sessions */}
270	      <V2Reveal delay={150}>
271	        <V2SectionCard
272	          t={t}
273	          title="Active Sessions"
274	          subtitle={`${sessions.length} device${sessions.length !== 1 ? 's' : ''} signed in`}
275	          action={
276	            <Box sx={{ display: 'flex', gap: `${t.space[8]}px`, flexWrap: 'wrap' }}>
277	              <V2Button t={t} variant="secondary" size="sm" onClick={() => refetchSessions()}>
278	                Refresh
279	              </V2Button>
280	              <V2Button
281	                t={t}
282	                variant="secondary"
283	                size="sm"
284	                onClick={() => setConfirmAction({ type: 'logout-all' })}
285	              >
286	                Sign out other devices
287	              </V2Button>
288	            </Box>
289	          }
290	        >
291	          <Box sx={{ display: 'flex', flexDirection: 'column', gap: `${t.space[12]}px` }}>
292	            {sortedSessions.map((session: SessionInfo) => {
293	              const isCurrentSession = session.id === currentSessionId;
294	              const isExpanded = expandedSessions.has(session.id);
295	
296	              return (
297	                <Box key={session.id} sx={panelSx(t)}>
298	                  <Box
299	                    sx={{
300	                      display: 'flex',
301	                      alignItems: 'center',
302	                      justifyContent: 'space-between',
303	                      flexWrap: 'wrap',
304	                      gap: `${t.space[16]}px`,
305	                    }}
306	                  >
307	                    <Box sx={{ display: 'flex', alignItems: 'center', gap: `${t.space[16]}px`, flex: 1 }}>
308	                      {getDeviceIcon(session.user_agent)}
309	                      <Box>
310	                        <Box sx={{ display: 'flex', alignItems: 'center', gap: `${t.space[8]}px`, mb: `${t.space[4]}px` }}>
311	                          <Typography sx={{ ...v2Typography.sectionTitle, color: t.text }}>
312	                            {parseDeviceName(session.user_agent)}
313	                          </Typography>
314	                          {isCurrentSession && (
315	                            <V2StatusBadge t={t} severity="positive" label="Most recent" />
316	                          )}
317	                        </Box>
318	                        <Typography sx={{ ...v2Typography.body, color: t.textMuted }}>
319	                          {session.ip_address || 'Unknown location'} • Last active{' '}
320	                          <Box component="span" sx={{ minWidth: '52px', display: 'inline-block' }}>
321	                            {formatLastActive(session.last_used_at)}
322	                          </Box>
323	                        </Typography>
324	                      </Box>
325	                    </Box>
326	
327	                    <Box sx={{ display: 'flex', gap: `${t.space[8]}px` }}>
328	                      <V2Button
329	                        t={t}
330	                        variant="secondary"
331	                        size="sm"
332	                        icon={
333	                          <ExpandMore
334	                            sx={{
335	                              fontSize: 16,
336	                              transform: isExpanded ? 'rotate(180deg)' : 'rotate(0)',
337	                              transition: 'transform 160ms ease',
338	                            }}
339	                          />
340	                        }
341	                        onClick={() => toggleSessionDetails(session.id)}
342	                      >
343	                        Details
344	                      </V2Button>
345	                      {!isCurrentSession && (
346	                        <V2Button
347	                          t={t}
348	                          variant="secondary"
349	                          size="sm"
350	                          onClick={() => setConfirmAction({ type: 'sign-out', sessionId: session.id })}
351	                        >
352	                          Sign out
353	                        </V2Button>
354	                      )}
355	                    </Box>
356	                  </Box>
357	
358	                  <Collapse in={isExpanded}>
359	                    <Box
360	                      sx={{
361	                        mt: `${t.space[16]}px`,
362	                        pt: `${t.space[16]}px`,
363	                        borderTop: `1px solid ${t.borderSubtle}`,
364	                      }}
365	                    >
366	                      <Typography sx={{ ...sectionLabel(t), mb: `${t.space[12]}px` }}>
367	                        Session details
368	                      </Typography>
369	                      <Box sx={{ display: 'flex', flexDirection: 'column', gap: `${t.space[8]}px` }}>
370	                        <Box>
371	                          <Typography sx={{ ...v2Typography.bodySmall, color: t.textMuted }}>
372	                            IP Address
373	                          </Typography>
374	                          <Typography sx={{ ...v2Typography.body, ...tnum, color: t.text }}>
375	                            {session.ip_address || 'Not available'}
376	                          </Typography>
377	                        </Box>
378	                        <Box>
379	                          <Typography sx={{ ...v2Typography.bodySmall, color: t.textMuted }}>
380	                            Created
381	                          </Typography>
382	                          <Typography sx={{ ...v2Typography.body, ...tnum, color: t.text }}>
383	                            {new Date(session.created_at).toLocaleString()}
384	                          </Typography>
385	                        </Box>
386	                        <Box>
387	                          <Typography sx={{ ...v2Typography.bodySmall, color: t.textMuted }}>
388	                            Expires
389	                          </Typography>
390	                          <Typography sx={{ ...v2Typography.body, ...tnum, color: t.text }}>
391	                            {new Date(session.expires_at).toLocaleString()}
392	                          </Typography>
393	                        </Box>
