import { useState, useEffect, useRef } from 'react';
import { Box, Typography, Collapse } from '@mui/material';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import {
  Laptop,
  Smartphone,
  Computer,
  Mail,
  Public,
  ExpandMore,
  Info,
} from '@mui/icons-material';
import { useV2Tokens, v2Typography } from '../../v2/tokens';
import { V2SectionCard } from '../../v2/V2SectionCard';
import { V2Reveal } from '../../v2/V2Reveal';
import { V2StatusBadge } from '../../v2/V2StatusBadge';
import { V2Button } from '../../v2/V2Button';
import { V2Modal } from '../../v2/V2Modal';
import { V2Callout } from '../../v2/V2Callout';
import {
  listSessions,
  revokeSession,
  logoutAllSessions,
  listConnectedAccounts,
  linkGoogle,
  unlinkGoogle,
} from '../../../lib/endpoints';
import { useAuth } from '../../../contexts/AuthContext';
import type { SessionInfo } from '../../../types';
import { panelSx, sectionLabel, tnum, bodyText } from '../styles';

import { config } from '../../../config';

const GOOGLE_CLIENT_ID = config.GOOGLE_CLIENT_ID;

export function SecurityTab() {
  const t = useV2Tokens();
  const queryClient = useQueryClient();
  const { user } = useAuth();
  const [expandedSessions, setExpandedSessions] = useState<Set<string>>(new Set());
  const [confirmAction, setConfirmAction] = useState<{ type: 'logout-all' | 'sign-out' | 'disconnect-google'; sessionId?: string } | null>(null);
  const [googleConnecting, setGoogleConnecting] = useState(false);
  const [googleError, setGoogleError] = useState('');
  const gsiReady = useRef(false);

  useEffect(() => {
    if (!GOOGLE_CLIENT_ID) return;
    if ((window as any).google) { gsiReady.current = true; return; }
    const script = document.createElement('script');
    script.src = 'https://accounts.google.com/gsi/client';
    script.async = true;
    script.onload = () => { gsiReady.current = true; };
    document.head.appendChild(script);
  }, []);

  const { data: sessions = [], refetch: refetchSessions } = useQuery({
    queryKey: ['sessions'],
    queryFn: listSessions,
  });

  const { data: connectedAccounts = [], refetch: refetchConnectedAccounts } = useQuery({
    queryKey: ['connectedAccounts', user?.id],
    queryFn: listConnectedAccounts,
    enabled: !!user?.id,
  });

  const revokeMutation = useMutation({
    mutationFn: revokeSession,
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['sessions'] });
    },
  });

  const logoutAllMutation = useMutation({
    mutationFn: logoutAllSessions,
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['sessions'] });
    },
  });

  const unlinkGoogleMutation = useMutation({
    mutationFn: unlinkGoogle,
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['connectedAccounts'] });
    },
  });

  const toggleSessionDetails = (sessionId: string) => {
    setExpandedSessions((prev) => {
      const next = new Set(prev);
      if (next.has(sessionId)) {
        next.delete(sessionId);
      } else {
        next.add(sessionId);
      }
      return next;
    });
  };

  const parseDeviceName = (userAgent: string | null): string => {
    if (!userAgent) return 'Unknown Device';
    if (userAgent.includes('iPhone') || userAgent.includes('iPad')) return 'iPhone';
    if (userAgent.includes('Android')) return 'Android Phone';
    if (userAgent.includes('Mac')) return 'MacBook';
    if (userAgent.includes('Windows')) return 'Windows PC';
    if (userAgent.includes('Linux')) return 'Linux Desktop';
    return 'Web Browser';
  };

  const getDeviceIcon = (userAgent: string | null) => {
    if (!userAgent) return <Computer sx={{ fontSize: 22, color: t.textSub }} />;
    if (userAgent.includes('iPhone') || userAgent.includes('iPad') || userAgent.includes('Android')) {
      return <Smartphone sx={{ fontSize: 22, color: t.textSub }} />;
    }
    return <Laptop sx={{ fontSize: 22, color: t.textSub }} />;
  };

  const formatLastActive = (lastUsedAt: string | null): string => {
    if (!lastUsedAt) return 'Never';
    const date = new Date(lastUsedAt);
    const now = new Date();
    const diffMs = now.getTime() - date.getTime();
    const diffMins = Math.floor(diffMs / 60000);
    if (diffMins < 1) return 'Just now';
    if (diffMins < 60) return `${diffMins}m ago`;
    const diffHours = Math.floor(diffMins / 60);
    if (diffHours < 24) return `${diffHours}h ago`;
    const diffDays = Math.floor(diffHours / 24);
    if (diffDays === 1) return 'Yesterday';
    if (diffDays < 7) return `${diffDays}d ago`;
    return date.toLocaleDateString();
  };

  const sortedSessions = [...sessions].sort((a, b) => {
    const aTime = a.last_used_at ? new Date(a.last_used_at).getTime() : 0;
    const bTime = b.last_used_at ? new Date(b.last_used_at).getTime() : 0;
    return bTime - aTime;
  });
  const currentSessionId = sortedSessions[0]?.id || null;
  const googleAccount = connectedAccounts.find((acc) => acc.provider === 'google');

  const confirmTitle =
    confirmAction?.type === 'logout-all' ? 'Sign out other devices'
    : confirmAction?.type === 'sign-out' ? 'Sign out device'
    : confirmAction?.type === 'disconnect-google' ? 'Disconnect Google'
    : '';

  const confirmBody =
    confirmAction?.type === 'logout-all' ? 'This will sign out all other sessions. You will remain signed in on this device.'
    : confirmAction?.type === 'sign-out' ? 'This will end the session on that device. They will need to sign in again.'
    : confirmAction?.type === 'disconnect-google' ? 'This will remove Google as a sign-in method. You can reconnect later.'
    : '';

  const handleConfirm = () => {
    if (confirmAction?.type === 'logout-all') {
      logoutAllMutation.mutate();
    } else if (confirmAction?.type === 'sign-out' && confirmAction.sessionId) {
      revokeMutation.mutate(confirmAction.sessionId);
    } else if (confirmAction?.type === 'disconnect-google') {
      unlinkGoogleMutation.mutate();
    }
    setConfirmAction(null);
  };

  return (
    <Box sx={{ display: 'flex', flexDirection: 'column', gap: `${t.space[24]}px` }}>
      {/* Section 1: Sign-in Methods (moved above sessions) */}
      <V2Reveal delay={0}>
        <V2SectionCard t={t} title="Sign-in Methods" subtitle="Connected authentication methods">
          <Box sx={{ display: 'flex', flexDirection: 'column', gap: `${t.space[12]}px` }}>
            {/* Email & Password */}
            <Box
              sx={{
                ...panelSx(t),
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'space-between',
                flexWrap: 'wrap',
                gap: `${t.space[16]}px`,
              }}
            >
              <Box sx={{ display: 'flex', alignItems: 'center', gap: `${t.space[16]}px` }}>
                <Mail sx={{ fontSize: 22, color: t.accent }} />
                <Box>
                  <Typography sx={{ ...v2Typography.sectionTitle, color: t.text, mb: `${t.space[4]}px` }}>
                    Email &amp; password
                  </Typography>
                  <Typography sx={{ ...v2Typography.body, color: t.textMuted }}>
                    {user?.email}
                  </Typography>
                </Box>
              </Box>
              <V2StatusBadge t={t} severity="positive" label="Active" />
            </Box>

            {/* Google */}
            <Box
              sx={{
                ...panelSx(t),
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'space-between',
                flexWrap: 'wrap',
                gap: `${t.space[16]}px`,
              }}
            >
              <Box sx={{ display: 'flex', alignItems: 'center', gap: `${t.space[16]}px` }}>
                <Public sx={{ fontSize: 22, color: googleAccount ? t.accent : t.textMuted }} />
                <Box>
                  <Typography sx={{ ...v2Typography.sectionTitle, color: t.text, mb: `${t.space[4]}px` }}>
                    Google
                  </Typography>
                  <Typography sx={{ ...v2Typography.body, color: t.textMuted }}>
                    {googleAccount
                      ? googleAccount.email || 'Connected'
                      : 'Not connected'}
                  </Typography>
                </Box>
              </Box>
              {googleAccount ? (
                <V2Button
                  t={t}
                  variant="secondary"
                  onClick={() => setConfirmAction({ type: 'disconnect-google' })}
                >
                  Disconnect
                </V2Button>
              ) : GOOGLE_CLIENT_ID ? (
                <Box sx={{ display: 'flex', alignItems: 'center', gap: `${t.space[8]}px` }}>
                  {googleError && (
                    <Typography sx={{ ...v2Typography.bodySmall, color: t.alert.warningText }}>{googleError}</Typography>
                  )}
                  <V2Button
                    t={t}
                    variant="secondary"
                    loading={googleConnecting}
                    onClick={() => {
                      if (!gsiReady.current || !GOOGLE_CLIENT_ID) return;
                      setGoogleError('');
                      setGoogleConnecting(true);
                      const google = (window as any).google;
                      google.accounts.id.initialize({
                        client_id: GOOGLE_CLIENT_ID,
                        callback: async (resp: { credential: string }) => {
                          try {
                            await linkGoogle(resp.credential);
                            refetchConnectedAccounts();
                          } catch {
                            setGoogleError('Failed to link Google account');
                          } finally {
                            setGoogleConnecting(false);
                          }
                        },
                      });
                      google.accounts.id.prompt();
                    }}
                  >
                    {googleConnecting ? 'Connecting...' : 'Connect'}
                  </V2Button>
                </Box>
              ) : (
                <Typography sx={{ ...v2Typography.bodySmall, color: t.textMuted }}>Not configured</Typography>
              )}
            </Box>
          </Box>
        </V2SectionCard>
      </V2Reveal>

      {/* Section 2: Active Sessions */}
      <V2Reveal delay={150}>
        <V2SectionCard
          t={t}
          title="Active Sessions"
          subtitle={`${sessions.length} device${sessions.length !== 1 ? 's' : ''} signed in`}
          action={
            <Box sx={{ display: 'flex', gap: `${t.space[8]}px`, flexWrap: 'wrap' }}>
              <V2Button t={t} variant="secondary" size="sm" onClick={() => refetchSessions()}>
                Refresh
              </V2Button>
              <V2Button
                t={t}
                variant="secondary"
                size="sm"
                onClick={() => setConfirmAction({ type: 'logout-all' })}
              >
                Sign out other devices
              </V2Button>
            </Box>
          }
        >
          <Box sx={{ display: 'flex', flexDirection: 'column', gap: `${t.space[12]}px` }}>
            {sortedSessions.map((session: SessionInfo) => {
              const isCurrentSession = session.id === currentSessionId;
              const isExpanded = expandedSessions.has(session.id);

              return (
                <Box key={session.id} sx={panelSx(t)}>
                  <Box
                    sx={{
                      display: 'flex',
                      alignItems: 'center',
                      justifyContent: 'space-between',
                      flexWrap: 'wrap',
                      gap: `${t.space[16]}px`,
                    }}
                  >
                    <Box sx={{ display: 'flex', alignItems: 'center', gap: `${t.space[16]}px`, flex: 1 }}>
                      {getDeviceIcon(session.user_agent)}
                      <Box>
                        <Box sx={{ display: 'flex', alignItems: 'center', gap: `${t.space[8]}px`, mb: `${t.space[4]}px` }}>
                          <Typography sx={{ ...v2Typography.sectionTitle, color: t.text }}>
                            {parseDeviceName(session.user_agent)}
                          </Typography>
                          {isCurrentSession && (
                            <V2StatusBadge t={t} severity="positive" label="Most recent" />
                          )}
                        </Box>
                        <Typography sx={{ ...v2Typography.body, color: t.textMuted }}>
                          {session.ip_address || 'Unknown location'} • Last active{' '}
                          <Box component="span" sx={{ minWidth: '52px', display: 'inline-block' }}>
                            {formatLastActive(session.last_used_at)}
                          </Box>
                        </Typography>
                      </Box>
                    </Box>

                    <Box sx={{ display: 'flex', gap: `${t.space[8]}px` }}>
                      <V2Button
                        t={t}
                        variant="secondary"
                        size="sm"
                        icon={
                          <ExpandMore
                            sx={{
                              fontSize: 16,
                              transform: isExpanded ? 'rotate(180deg)' : 'rotate(0)',
                              transition: 'transform 160ms ease',
                            }}
                          />
                        }
                        onClick={() => toggleSessionDetails(session.id)}
                      >
                        Details
                      </V2Button>
                      {!isCurrentSession && (
                        <V2Button
                          t={t}
                          variant="secondary"
                          size="sm"
                          onClick={() => setConfirmAction({ type: 'sign-out', sessionId: session.id })}
                        >
                          Sign out
                        </V2Button>
                      )}
                    </Box>
                  </Box>

                  <Collapse in={isExpanded}>
                    <Box
                      sx={{
                        mt: `${t.space[16]}px`,
                        pt: `${t.space[16]}px`,
                        borderTop: `1px solid ${t.borderSubtle}`,
                      }}
                    >
                      <Typography sx={{ ...sectionLabel(t), mb: `${t.space[12]}px` }}>
                        Session details
                      </Typography>
                      <Box sx={{ display: 'flex', flexDirection: 'column', gap: `${t.space[8]}px` }}>
                        <Box>
                          <Typography sx={{ ...v2Typography.bodySmall, color: t.textMuted }}>
                            IP Address
                          </Typography>
                          <Typography sx={{ ...v2Typography.body, ...tnum, color: t.text }}>
                            {session.ip_address || 'Not available'}
                          </Typography>
                        </Box>
                        <Box>
                          <Typography sx={{ ...v2Typography.bodySmall, color: t.textMuted }}>
                            Created
                          </Typography>
                          <Typography sx={{ ...v2Typography.body, ...tnum, color: t.text }}>
                            {new Date(session.created_at).toLocaleString()}
                          </Typography>
                        </Box>
                        <Box>
                          <Typography sx={{ ...v2Typography.bodySmall, color: t.textMuted }}>
                            Expires
                          </Typography>
                          <Typography sx={{ ...v2Typography.body, ...tnum, color: t.text }}>
                            {new Date(session.expires_at).toLocaleString()}
                          </Typography>
                        </Box>
                      </Box>
                    </Box>
                  </Collapse>
                </Box>
              );
            })}

            {sessions.length === 0 && (
              <Box sx={{ textAlign: 'center', py: `${t.space[24]}px` }}>
                <Typography sx={{ ...v2Typography.body, color: t.textMuted }}>
                  No active sessions
                </Typography>
              </Box>
            )}
          </Box>
        </V2SectionCard>
      </V2Reveal>

      {/* Info Note — informational disclosure, so it renders on the semantic
          `info` family (teal). The pre-migration note hardcoded the C1
          `t.blue` Tailwind hue, which the recorded rulings forbid on product
          surfaces. */}
      <V2Reveal delay={200}>
        <V2Callout
          t={t}
          severity="info"
          icon={<Info sx={{ fontSize: 18 }} />}
          title="About session locations"
          detail="Location may be unavailable for VPN connections, corporate networks, or mobile data. IP addresses are logged for security purposes only."
        />
      </V2Reveal>

      {/* Confirmation Dialog */}
      <V2Modal
        t={t}
        open={!!confirmAction}
        onClose={() => setConfirmAction(null)}
        title={confirmTitle}
        actions={
          <>
            <V2Button t={t} variant="secondary" onClick={() => setConfirmAction(null)}>
              Cancel
            </V2Button>
            <V2Button t={t} variant="primary" onClick={handleConfirm}>
              Confirm
            </V2Button>
          </>
        }
      >
        <Typography sx={bodyText(t)}>{confirmBody}</Typography>
      </V2Modal>
    </Box>
  );
}

