1	import { ReactNode, useState } from 'react';
2	import { Box, Typography, CircularProgress } from '@mui/material';
3	import { V2Tokens } from './tokens';
4	
5	export type V2ButtonVariant = 'primary' | 'secondary' | 'ghost' | 'danger' | 'link';
6	
7	interface V2ButtonProps {
8	  t: V2Tokens;
9	  variant?: V2ButtonVariant;
10	  size?: 'sm' | 'md';
11	  icon?: ReactNode;
12	  children: ReactNode;
13	  onClick?: () => void;
14	  disabled?: boolean;
15	  /** Shows a spinner and blocks interaction while the caller's action is in
16	   *  flight. Presentation only — the caller owns when the action runs. */
17	  loading?: boolean;
18	  /** RUS-5897 (additive, chipHeight/iconBoxSize precedent): renders
19	   * `data-testid` on the root for callers whose flows are driven by test ids
20	   * (e.g. fireEvent.click must reach THIS element, not an outer wrapper).
21	   * Omitted → renders nothing extra; every existing consumer is unchanged. */
22	  testId?: string;
23	  /** RUS-5936 (additive, testId precedent): accessible name override for
24	   * links whose visible text is context-free (e.g. "Edit" inside a Review
25	   * summary row needs "Edit Personal Info"). Omitted → the visible children
26	   * remain the accessible name; every existing consumer is unchanged. */
27	  ariaLabel?: string;
28	}
29	
30	// B1 (RUS-5795 frozen contract): the only action button.
31	//
32	// Radius — Arbiter ruling R13: the FILLED variants (primary/secondary/danger)
33	// use `radius.card` (12, Figma primary `5211:7013`); ghost and link use
34	// `radius.control` (8, Figma ghost `5211:7128`). Deliberate variant-level
35	// distinction — not a contradiction, and no new button-radius token.
36	//
37	// Primary is FLAT: Figma's primary is flat and `btnGrad` is removed in F1
38	// (token-map). Fill is `t.accent` with the RUS-5751 accessible `t.btnText`
39	// foreground (never `#fff` — see design/tokens.ts primary.contrast), the
40	// `effect.buttonGlass` inset highlight + glass border carry the Figma glass
41	// treatment. `effect.buttonGlass` is Figma-evidenced in DARK mode only; in
42	// LIGHT mode the token is 'none' after the RUS-5797 light-glass verification
43	// (no light-mode button node exists in the recorded extraction), so light
44	// primary is simply flat — see design/tokens.ts effect.buttonGlass.
45	export function V2Button({ t, variant = 'secondary', size = 'md', icon, children, onClick, disabled, loading, testId, ariaLabel }: V2ButtonProps) {
46	  const [hov, setHov] = useState(false);
47	
48	  // B1 frozen geometry: h32 md / h28 sm; primary spec is 12/18 Medium.
49	  const height = size === 'sm' ? 28 : 32;
50	  const fontSize = size === 'sm' ? 11 : 12;
51	  const px = size === 'sm' ? 1.25 : 1.75;
52	
53	  const inert = disabled || loading;
54	
55	  // Keyboard focus ring (pattern shared with V2SegmentedControl): suppressed
56	  // after pointer clicks, visible ring for keyboard users.
57	  const focusRing = {
58	    outline: 'none',
59	    '&:focus': { outline: 'none' },
60	    '&:focus-visible': inert ? {} : {
61	      outline: 'none',
62	      borderColor: t.accent,
63	      boxShadow: `${variant === 'primary' && t.effect.buttonGlass !== 'none' ? `${t.effect.buttonGlass}, ` : ''}0 0 0 2px ${t.accentDim}`,
64	    },
65	  };
66	
67	  // Radius (R13): filled variants 12, ghost/link 8.
68	  const radius: Record<V2ButtonVariant, number> = {
69	    primary: t.radius.card,
70	    secondary: t.radius.card,
71	    danger: t.radius.card,
72	    ghost: t.radius.control,
73	    link: t.radius.control,
74	  };
75	
76	  const styles: Record<V2ButtonVariant, Record<string, any>> = {
77	    primary: {
78	      // FLAT accent fill (F1: btnGrad removed) + glass border + inset
79	      // highlight (dark; 'none' in light after the light-glass disposition).
80	      background: hov && !inert ? t.effect.buttonGradientHover : t.accent,
81	      color: t.btnText,
82	      border: `1px solid ${t.accentBorder}`,
83	      boxShadow: !inert && t.effect.buttonGlass !== 'none' ? t.effect.buttonGlass : 'none',
84	    },
85	    secondary: {
86	      background: 'transparent',
87	      color: t.text,
88	      border: `1px solid ${hov && !inert ? t.borderHover : t.border}`,
89	    },
90	    ghost: {
91	      background: hov && !inert ? `${t.accent}08` : 'transparent',
92	      color: t.textSub,
93	      border: 'none',
94	    },
95	    danger: {
96	      background: hov && !inert ? `${t.negative}12` : `${t.negative}08`,
97	      color: t.negative,
98	      border: `1px solid ${t.negative}28`,
99	    },
100	    link: {
101	      // K2 `5265:1107`: text-link + trailing arrow; Manrope (fixes anomaly A2
102	      // — the Figma source showed the legacy mono face). No chrome.
103	      background: 'transparent',
104	      color: t.accent,
105	      border: 'none',
106	      height: 'auto',
107	      px: 0.25,
108	      '&:hover': inert ? undefined : { textDecoration: 'underline' },
109	    },
110	  };
111	
112	  const s = styles[variant];
113	
114	  return (
115	    <Box
116	      component="button"
117	      type="button"
118	      data-testid={testId}
119	      aria-label={ariaLabel}
120	      disabled={inert}
121	      aria-busy={loading || undefined}
122	      onClick={inert ? undefined : onClick}
123	      onMouseEnter={() => setHov(true)}
124	      onMouseLeave={() => setHov(false)}
125	      sx={{
126	        display: 'inline-flex',
127	        alignItems: 'center',
128	        justifyContent: 'center',
129	        gap: 0.5,
130	        height,
131	        px,
132	        borderRadius: `${radius[variant]}px`,
133	        cursor: inert ? (loading ? 'wait' : 'not-allowed') : 'pointer',
134	        opacity: disabled ? 0.5 : 1,
135	        transition: 'all 180ms ease',
136	        ...focusRing,
137	        ...s,
138	      }}
139	    >
140	      {loading ? (
141	        <CircularProgress size={fontSize + 2} sx={{ color: 'inherit', flexShrink: 0 }} />
142	      ) : (
143	        icon && variant !== 'link' && (
144	          <Box sx={{ display: 'flex', alignItems: 'center', flexShrink: 0 }}>{icon}</Box>
145	        )
146	      )}
147	      <Typography sx={{ fontSize, fontWeight: 500, lineHeight: '18px', whiteSpace: 'nowrap', color: 'inherit' }}>
