import { ReactNode, useState } from 'react';
import { Box, Typography, CircularProgress } from '@mui/material';
import { V2Tokens } from './tokens';

export type V2ButtonVariant = 'primary' | 'secondary' | 'ghost' | 'danger' | 'link';

interface V2ButtonProps {
  t: V2Tokens;
  variant?: V2ButtonVariant;
  size?: 'sm' | 'md';
  icon?: ReactNode;
  children: ReactNode;
  onClick?: () => void;
  disabled?: boolean;
  /** Shows a spinner and blocks interaction while the caller's action is in
   *  flight. Presentation only — the caller owns when the action runs. */
  loading?: boolean;
  /** RUS-5897 (additive, chipHeight/iconBoxSize precedent): renders
   * `data-testid` on the root for callers whose flows are driven by test ids
   * (e.g. fireEvent.click must reach THIS element, not an outer wrapper).
   * Omitted → renders nothing extra; every existing consumer is unchanged. */
  testId?: string;
  /** RUS-5936 (additive, testId precedent): accessible name override for
   * links whose visible text is context-free (e.g. "Edit" inside a Review
   * summary row needs "Edit Personal Info"). Omitted → the visible children
   * remain the accessible name; every existing consumer is unchanged. */
  ariaLabel?: string;
}

// B1 (RUS-5795 frozen contract): the only action button.
//
// Radius — Arbiter ruling R13: the FILLED variants (primary/secondary/danger)
// use `radius.card` (12, Figma primary `5211:7013`); ghost and link use
// `radius.control` (8, Figma ghost `5211:7128`). Deliberate variant-level
// distinction — not a contradiction, and no new button-radius token.
//
// Primary is FLAT: Figma's primary is flat and `btnGrad` is removed in F1
// (token-map). Fill is `t.accent` with the RUS-5751 accessible `t.btnText`
// foreground (never `#fff` — see design/tokens.ts primary.contrast), the
// `effect.buttonGlass` inset highlight + glass border carry the Figma glass
// treatment. `effect.buttonGlass` is Figma-evidenced in DARK mode only; in
// LIGHT mode the token is 'none' after the RUS-5797 light-glass verification
// (no light-mode button node exists in the recorded extraction), so light
// primary is simply flat — see design/tokens.ts effect.buttonGlass.
export function V2Button({ t, variant = 'secondary', size = 'md', icon, children, onClick, disabled, loading, testId, ariaLabel }: V2ButtonProps) {
  const [hov, setHov] = useState(false);

  // B1 frozen geometry: h32 md / h28 sm; primary spec is 12/18 Medium.
  const height = size === 'sm' ? 28 : 32;
  const fontSize = size === 'sm' ? 11 : 12;
  const px = size === 'sm' ? 1.25 : 1.75;

  const inert = disabled || loading;

  // Keyboard focus ring (pattern shared with V2SegmentedControl): suppressed
  // after pointer clicks, visible ring for keyboard users.
  const focusRing = {
    outline: 'none',
    '&:focus': { outline: 'none' },
    '&:focus-visible': inert ? {} : {
      outline: 'none',
      borderColor: t.accent,
      boxShadow: `${variant === 'primary' && t.effect.buttonGlass !== 'none' ? `${t.effect.buttonGlass}, ` : ''}0 0 0 2px ${t.accentDim}`,
    },
  };

  // Radius (R13): filled variants 12, ghost/link 8.
  const radius: Record<V2ButtonVariant, number> = {
    primary: t.radius.card,
    secondary: t.radius.card,
    danger: t.radius.card,
    ghost: t.radius.control,
    link: t.radius.control,
  };

  const styles: Record<V2ButtonVariant, Record<string, any>> = {
    primary: {
      // FLAT accent fill (F1: btnGrad removed) + glass border + inset
      // highlight (dark; 'none' in light after the light-glass disposition).
      background: hov && !inert ? t.effect.buttonGradientHover : t.accent,
      color: t.btnText,
      border: `1px solid ${t.accentBorder}`,
      boxShadow: !inert && t.effect.buttonGlass !== 'none' ? t.effect.buttonGlass : 'none',
    },
    secondary: {
      background: 'transparent',
      color: t.text,
      border: `1px solid ${hov && !inert ? t.borderHover : t.border}`,
    },
    ghost: {
      background: hov && !inert ? `${t.accent}08` : 'transparent',
      color: t.textSub,
      border: 'none',
    },
    danger: {
      background: hov && !inert ? `${t.negative}12` : `${t.negative}08`,
      color: t.negative,
      border: `1px solid ${t.negative}28`,
    },
    link: {
      // K2 `5265:1107`: text-link + trailing arrow; Manrope (fixes anomaly A2
      // — the Figma source showed the legacy mono face). No chrome.
      background: 'transparent',
      color: t.accent,
      border: 'none',
      height: 'auto',
      px: 0.25,
      '&:hover': inert ? undefined : { textDecoration: 'underline' },
    },
  };

  const s = styles[variant];

  return (
    <Box
      component="button"
      type="button"
      data-testid={testId}
      aria-label={ariaLabel}
      disabled={inert}
      aria-busy={loading || undefined}
      onClick={inert ? undefined : onClick}
      onMouseEnter={() => setHov(true)}
      onMouseLeave={() => setHov(false)}
      sx={{
        display: 'inline-flex',
        alignItems: 'center',
        justifyContent: 'center',
        gap: 0.5,
        height,
        px,
        borderRadius: `${radius[variant]}px`,
        cursor: inert ? (loading ? 'wait' : 'not-allowed') : 'pointer',
        opacity: disabled ? 0.5 : 1,
        transition: 'all 180ms ease',
        ...focusRing,
        ...s,
      }}
    >
      {loading ? (
        <CircularProgress size={fontSize + 2} sx={{ color: 'inherit', flexShrink: 0 }} />
      ) : (
        icon && variant !== 'link' && (
          <Box sx={{ display: 'flex', alignItems: 'center', flexShrink: 0 }}>{icon}</Box>
        )
      )}
      <Typography sx={{ fontSize, fontWeight: 500, lineHeight: '18px', whiteSpace: 'nowrap', color: 'inherit' }}>
        {children}
      </Typography>
      {variant === 'link' && icon && (
        <Box sx={{ display: 'flex', alignItems: 'center', flexShrink: 0 }}>{icon}</Box>
      )}
    </Box>
  );
}

import { ReactNode } from 'react';
import { Box, Typography, Dialog } from '@mui/material';
import { Close } from '@mui/icons-material';
import { V2Tokens } from './tokens';
import { V2IconButton } from './V2IconButton';

interface V2ModalProps {
  t: V2Tokens;
  open: boolean;
  onClose: () => void;
  /** Title text — ignored when `header` is supplied. */
  title?: ReactNode;
  /** Optional muted line under the title (e.g. a step label). */
  subtitle?: ReactNode;
  /** Full custom header slot (overrides `title`/`icon`). */
  header?: ReactNode;
  children: ReactNode;
  /** Footer action slot (normally `V2Button`s). The Kit renders it; it does
   *  NOT own submit/validate/entitlement logic — the caller supplies the
   *  buttons and their disabled state (B9). */
  actions?: ReactNode;
  /** Optional header icon, rendered in the 36×36 accent chip. */
  icon?: ReactNode;
  /** Maps to the paper max-width: 'sm' → 480px, 'md' → 520px. The mobile
   *  full-width rule comes from the MuiDialog theme override. */
  size?: 'sm' | 'md';
  /** Default true: the paper is a flex column with a fixed header/footer and
   *  a scrolling body (WS4: the footer stays reachable on short screens). */
  scrollBody?: boolean;
  /** Chrome slot pinned between the header and the scroll body (e.g. the
   *  RUS-5762 inline submission error, which must stay readable while the
   *  user corrects fields). Content-neutral — the Kit renders whatever is
   *  given. */
  banner?: ReactNode;
  /** RUS-5939 (additive, `V2Button`/`V2SectionCard` testId precedent): the
   *  Alerts wizard moves off its hand-rolled `zIndex:9999` overlay onto this
   *  chrome, but two e2e specs scope every wizard interaction to
   *  `[data-testid="alert-wizard"]`. Dialogs are PORTALED, so a wrapper
   *  element cannot carry that id — it has to sit on the dialog root.
   *  Omitted (the default) renders nothing: existing consumers unaffected. */
  testId?: string;
}

// B9 (RUS-5795 frozen contract, concretely specified by Arbiter ruling R17):
// the shared modal/dialog CHROME the kit dialogs are built on.
//
// Visual: paper radius `radius.card` (12 — Figma dialog 16 → 12 in F1; the
// 18px pre-Kit literal is drift), bg `t.cardElevated` (replaces the
// `#0F252B → #123139` surface sweep hardcoded in the old dialogs), border
// `1px t.accentBorder`, `effect.card` (border-driven, no glow) with the
// design system's dialog elevation shadow, padding `space[24]` (the 28px
// pre-Kit literal moved to the nearest frozen token), header icon chip
// 36×36 `radius.control` (`t.accentDim` bg + `t.accent` icon), backdrop
// blur(4px) per the recorded dialog chrome (the scrim itself stays MUI's
// default — no backdrop colour token exists, and the Kit introduces no
// colour literal).
//
// Behavior: CHROME ONLY. It does not validate, submit, gate entitlements, or
// call endpoints. Guest mutations still route through GuestPreviewGate in the
// caller, outside this component.
export function V2Modal({
  t,
  open,
  onClose,
  title,
  subtitle,
  header,
  children,
  actions,
  icon,
  size = 'sm',
  scrollBody = true,
  banner,
  testId,
}: V2ModalProps) {
  const maxWidth = size === 'md' ? 520 : 480;

  return (
    <Dialog
      open={open}
      onClose={onClose}
      fullWidth
      maxWidth="sm"
      data-testid={testId}
      // Chrome hygiene carried over from the dialogs this replaces: pointer
      // events inside the dialog must not bubble to page-level click handlers.
      onClick={(e) => e.stopPropagation()}
      slotProps={{ backdrop: { sx: { backdropFilter: 'blur(4px)' } } }}
      PaperProps={{
        sx: {
          borderRadius: `${t.radius.card}px`,
          background: t.cardElevated,
          border: `1px solid ${t.accentBorder}`,
          // B9: effect.card is border-driven (E7) — no glow, no hand-rolled
          // elevation literal. Separation comes from the border, the
          // elevated surface and the blurred backdrop. The pre-Kit
          // `0 24px 64px rgba(0,0,0,0.6)` literal is removed, not re-tokenised.
          boxShadow: t.cardShadow,
          p: `${t.space[24]}px`,
          maxWidth,
          ...(scrollBody
            ? {
                // WS4: constrain height so the footer stays reachable on
                // small/short screens; 100dvh tracks the mobile keyboard.
                maxHeight: 'calc(100dvh - 96px)',
                display: 'flex',
                flexDirection: 'column',
                overflow: 'hidden',
                margin: '48px auto',
              }
            : {}),
        },
      }}
    >
      {header !== undefined ? (
        header
      ) : (
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1.5, mb: 3, flexShrink: 0 }}>
          {icon && (
            <Box
              sx={{
                width: 36,
                height: 36,
                borderRadius: `${t.radius.control}px`,
                background: t.accentDim,
                border: `1px solid ${t.accentBorder}`,
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                flexShrink: 0,
              }}
            >
              {icon}
            </Box>
          )}
          <Box sx={{ flex: 1, minWidth: 0 }}>
            <Typography
              sx={{ fontFamily: "'Manrope', sans-serif", fontWeight: 700, fontSize: 17, color: t.text }}
            >
              {title}
            </Typography>
            {subtitle && (
              <Typography sx={{ fontSize: 11, color: t.textMuted }}>{subtitle}</Typography>
            )}
          </Box>
          <V2IconButton t={t} icon={<Close sx={{ fontSize: 14 }} />} onClick={onClose} ariaLabel="Close" size={28} />
        </Box>
      )}

      {banner}

      {scrollBody ? (
        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2, flex: '1 1 auto', overflowY: 'auto', minHeight: 0, pr: 0.5 }}>
          {children}
        </Box>
      ) : (
        children
      )}

      {actions && (
        <Box
          sx={{
            display: 'flex',
            justifyContent: 'flex-end',
            gap: 1.25,
            mt: scrollBody ? 3 : 0,
            flexShrink: 0,
            ...(scrollBody ? { pt: 2, borderTop: `1px solid ${t.borderSubtle}` } : {}),
          }}
        >
          {actions}
        </Box>
      )}
    </Dialog>
  );
}

