import { useState, useRef } from 'react';
import { Box, Typography, Dialog, DialogTitle, DialogContent, DialogActions, Button } from '@mui/material';
import { AutoAwesomeOutlined, DownloadOutlined, CheckCircleOutline, WarningAmberOutlined } from '@mui/icons-material';
import { useQuery } from '@tanstack/react-query';
import { useV2Tokens } from '../../v2/tokens';
import { V2Reveal } from '../../v2/V2Reveal';
import { V2StatusBadge } from '../../v2/V2StatusBadge';
import { ActionButton } from '../components/ActionButton';
import { useAuth } from '../../../contexts/AuthContext';
import { useEntitlements } from '../../../hooks/useEntitlements';
import { useTokenUsage } from '../../../hooks/useTokenUsage';
import { useSubscription, usePaymentMethod, useInvoices, useCancelSubscription, useChangePlan, useReactivateSubscription } from '../../../lib/useBilling';
import { getPlans } from '../../../lib/endpoints';
import { FEATURE_LABELS, displayFeatureValue, PLAN_HIGHLIGHT_FEATURES, planDisplayName } from '../../../utils/subscriptionUtils';
import { PaymentMethodUpdateDialog } from '../../billing/PaymentMethodUpdateDialog';

interface SubscriptionBillingTabProps {
  onNavigate?: (page: string) => void;
}


export function SubscriptionBillingTab({ onNavigate }: SubscriptionBillingTabProps) {
  const t = useV2Tokens();
  const { user } = useAuth();
  const { plan, state, planInfo, planName } = useEntitlements();
  const { pools, isLoading: tokenLoading } = useTokenUsage();
  const { data: subscription } = useSubscription();
  const { data: paymentMethod } = usePaymentMethod();
  const { data: invoices } = useInvoices();

  const { data: plans, isLoading: plansLoading, isError: plansError, refetch: refetchPlans } = useQuery({ queryKey: ['plans'], queryFn: getPlans });
  const reactivateMutation = useReactivateSubscription();

  const planComparisonRef = useRef<HTMLDivElement>(null);
  const [billingInterval, setBillingInterval] = useState<'monthly' | 'annual'>('monthly');
  const [cancelDialogOpen, setCancelDialogOpen] = useState(false);
  const [paymentDialogOpen, setPaymentDialogOpen] = useState(false);
  const [planChangeTarget, setPlanChangeTarget] = useState<{ id: string; name: string; direction: 'upgrade' | 'downgrade' } | null>(null);
  const [cancelSuccess, setCancelSuccess] = useState(false);
  const [planChangeSuccess, setPlanChangeSuccess] = useState<string | null>(null);
  const cancelMutation = useCancelSubscription();
  const changePlanMutation = useChangePlan();

  if (!user) {
    return (
      <Box sx={{ p: 3 }}>
        <Typography sx={{ color: t.textMuted }}>Please sign in to view subscription details.</Typography>
      </Box>
    );
  }

  const currentPlan = plans?.find(p => p.plan_id === plan);
  const actualInterval = subscription?.billing_interval === 'year' ? 'annual' : 'monthly';
  const currentPrice = currentPlan
    ? Number(actualInterval === 'annual' ? currentPlan.price_annual : currentPlan.price_monthly) || 0
    : null;
  const isCancelling = subscription?.cancel_at_period_end === true;

  const getSubscriptionBadge = (): { severity: 'high' | 'medium' | 'low' | 'info' | 'positive'; label: string } => {
    const status = subscription?.status;
    if (!status || status === 'none') return { severity: 'info', label: 'No Subscription' };
    if (['active', 'trialing'].includes(status) && subscription?.cancel_at_period_end) return { severity: 'medium', label: 'Cancelling' };
    if (status === 'active') return { severity: 'positive', label: 'Active' };
    if (status === 'trialing') return { severity: 'info', label: 'Trial' };
    if (status === 'past_due') return { severity: 'high', label: 'Past Due' };
    if (status === 'canceled') return { severity: 'high', label: 'Canceled' };
    if (status === 'unpaid') return { severity: 'high', label: 'Unpaid' };
    if (status === 'paused') return { severity: 'medium', label: 'Paused' };
    return { severity: 'info', label: status.charAt(0).toUpperCase() + status.slice(1) };
  };

  const subscriptionBadge = getSubscriptionBadge();

  const formatDate = (dateStr: string | null) => {
    if (!dateStr) return 'N/A';
    return new Date(dateStr).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
  };

  const formatCurrency = (cents: number) => {
    return `$${(cents / 100).toFixed(2)}`;
  };

  const capitalizeFirst = (str: string) => str.charAt(0).toUpperCase() + str.slice(1);

  // Section 1: Current Plan Hero
  const renderHeroSection = () => (
    <V2Reveal delay={0}>
      <Box
        sx={{
          borderRadius: '14px',
          background: 'linear-gradient(135deg, rgba(20,184,166,0.08) 0%, rgba(59,130,246,0.06) 100%)',
          border: `1px solid ${t.accentBorder}`,
          boxShadow: t.cardShadow, transition: 'all 160ms ease', '&:hover': { background: t.cardElevated, borderColor: t.borderHover, boxShadow: t.hoverShadow, transform: 'translateY(-1px)' },
          p: { xs: 2, md: '28px 32px' },
          overflow: 'hidden',
          position: 'relative',
        }}
      >
        <Box sx={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', mb: 2.5 }}>
          <Box>
            <Typography sx={{ fontSize: 10, color: t.textMuted, textTransform: 'uppercase', fontWeight: 700, letterSpacing: '0.05em', mb: 0.5 }}>
              Current Plan
            </Typography>
            <Typography sx={{ fontFamily: "'Manrope', sans-serif", fontWeight: 800, fontSize: 28, color: t.text }}>
              {currentPlan?.name || planName}
            </Typography>
          </Box>
          <V2StatusBadge t={t} severity={subscriptionBadge.severity} label={subscriptionBadge.label} />
        </Box>

        <Box sx={{ display: 'flex', alignItems: 'baseline', gap: 0.5, mb: isCancelling ? 1.5 : 3 }}>
          {currentPrice !== null ? (
            <>
              <Typography sx={{ fontFamily: "'Manrope', sans-serif", fontWeight: 800, fontSize: 32, color: isCancelling ? t.textMuted : t.text, textDecoration: isCancelling ? 'line-through' : 'none' }}>
                ${currentPrice.toFixed(2)}
              </Typography>
              <Typography sx={{ fontSize: 14, color: t.textSub }}>
                /{actualInterval === 'annual' ? 'yr' : 'mo'}
              </Typography>
            </>
          ) : plansError ? (
            <Box component="button" onClick={() => refetchPlans()} sx={{ background: 'none', border: 'none', p: 0, cursor: 'pointer', fontFamily: 'inherit' }}>
              <Typography sx={{ fontSize: 13, color: t.negative }}>Failed to load pricing. <span style={{ textDecoration: 'underline' }}>Retry</span></Typography>
            </Box>
          ) : (
            <Typography sx={{ fontSize: 14, color: t.textMuted }}>Loading pricing...</Typography>
          )}
          {!isCancelling && currentPrice !== null && (
            <Typography sx={{ fontSize: 12, color: t.textMuted, ml: 1 }}>
              • Renews {formatDate(subscription?.next_invoice_date || null)}
            </Typography>
          )}
        </Box>

        {isCancelling && (
          <Box sx={{ mb: 3, p: 2, borderRadius: '10px', background: `${t.warning}10`, border: `1px solid ${t.warning}30` }}>
            <Typography sx={{ fontSize: 13, color: t.warning, fontWeight: 600, mb: 0.5 }}>
              Subscription cancelled
            </Typography>
            <Typography sx={{ fontSize: 12, color: t.textSub, lineHeight: 1.6 }}>
              Your plan will end on <strong style={{ color: t.text }}>{formatDate(subscription?.cancels_at || subscription?.current_period_end || null)}</strong>. You'll retain full access until then.
            </Typography>
          </Box>
        )}

        {subscription?.pending_plan_change && !isCancelling && (
          <Box sx={{ mb: 3, p: 2, borderRadius: '10px', background: `${t.accent}10`, border: `1px solid ${t.accent}30` }}>
            <Typography sx={{ fontSize: 13, color: t.accent, fontWeight: 600, mb: 0.5 }}>
              Plan change scheduled
            </Typography>
            <Typography sx={{ fontSize: 12, color: t.textSub, lineHeight: 1.6 }}>
              Your plan will change to <strong style={{ color: t.text }}>{planDisplayName(subscription.pending_plan_change.new_plan)}</strong> on <strong style={{ color: t.text }}>{formatDate(subscription.pending_plan_change.effective_at)}</strong>.
            </Typography>
          </Box>
        )}

        <Box sx={{ display: 'grid', gridTemplateColumns: { xs: '1fr', sm: 'repeat(2, 1fr)', md: 'repeat(4, 1fr)' }, gap: 2, mb: 3 }}>
          <Box>
            <Typography sx={{ fontSize: 10, color: t.textMuted, textTransform: 'uppercase', mb: 0.5, fontWeight: 700 }}>
              Billing Cycle
            </Typography>
            <Typography sx={{ fontSize: 14, fontWeight: 600, color: t.text }}>
              {capitalizeFirst(subscription?.billing_interval || 'monthly')}
            </Typography>
          </Box>
          <Box>
            <Typography sx={{ fontSize: 10, color: t.textMuted, textTransform: 'uppercase', mb: 0.5, fontWeight: 700 }}>
              Payment Method
            </Typography>
            <Typography sx={{ fontSize: 14, fontWeight: 600, color: t.text }}>
              {paymentMethod ? `${capitalizeFirst(paymentMethod.brand)} ···${paymentMethod.last4}` : 'None'}
            </Typography>
          </Box>
          <Box>
            <Typography sx={{ fontSize: 10, color: t.textMuted, textTransform: 'uppercase', mb: 0.5, fontWeight: 700 }}>
              Billing Email
            </Typography>
            <Typography sx={{ fontSize: 14, fontWeight: 600, color: t.text }}>
              {user.email}
            </Typography>
          </Box>
          <Box>
            <Typography sx={{ fontSize: 10, color: t.textMuted, textTransform: 'uppercase', mb: 0.5, fontWeight: 700 }}>
              Member Since
            </Typography>
            <Typography sx={{ fontSize: 14, fontWeight: 600, color: t.text }}>
              {user.created_at ? formatDate(user.created_at) : '—'}
            </Typography>
          </Box>
        </Box>

        {reactivateMutation.isError && (
          <Box sx={{ mb: 1.5, p: 1.5, borderRadius: '8px', background: `${t.negative}10`, border: `1px solid ${t.negative}30` }}>
            <Typography sx={{ fontSize: 12, color: t.negative, fontWeight: 500 }}>
              {(reactivateMutation.error as { response?: { data?: { error?: string } } })?.response?.data?.error || 'Failed to reactivate subscription. Please try again.'}
            </Typography>
          </Box>
        )}

        <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1.5, alignItems: 'center' }}>
          {isCancelling ? (
            <ActionButton
              t={t}
              label={reactivateMutation.isPending ? 'Reactivating...' : 'Reactivate subscription'}
              onClick={() => { if (!reactivateMutation.isPending) reactivateMutation.mutate(); }}
            />
          ) : (
            <>
              <ActionButton t={t} label="Change plan" onClick={() => planComparisonRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' })} />
              <ActionButton t={t} label="Update payment" onClick={() => setPaymentDialogOpen(true)} />
            </>
          )}
          <Box sx={{ flex: 1 }} />
          {subscription && ['active', 'trialing', 'past_due'].includes(subscription.status) && !subscription.cancel_at_period_end && (
            <Box
              component="button"
              onClick={() => setCancelDialogOpen(true)}
              sx={{
                background: 'none',
                border: 'none',
                color: t.textMuted,
                fontSize: 11,
                textDecoration: 'underline',
                cursor: 'pointer',
                padding: 0,
                fontFamily: 'inherit',
                '&:hover': { color: t.text },
              }}
            >
              Cancel subscription
            </Box>
          )}
        </Box>
      </Box>
    </V2Reveal>
  );

  // Section 2: AI Usage Progress
  const renderUsageSection = () => {
    const aiPool = pools.find(p => p.pool_key === 'ai_narratives');
    const used = aiPool?.tokens_used ?? null;
    const limit = aiPool?.tokens_limit ?? null;
    const pct = (used !== null && limit !== null && limit > 0) ? Math.min(used / limit, 1) : 0;
    const hasUsageData = used !== null && limit !== null;
    const resetsAt = planInfo?.usage?.ai_narratives?.resets_at;

    return (
      <V2Reveal delay={80}>
        <Box
          sx={{
            borderRadius: '14px',
            background: t.card,
            border: `1px solid ${t.border}`,
            boxShadow: t.cardShadow, transition: 'all 160ms ease', '&:hover': { background: t.cardElevated, borderColor: t.borderHover, boxShadow: t.hoverShadow, transform: 'translateY(-1px)' },
            p: '20px',
          }}
        >
          <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', mb: 2 }}>
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1.5 }}>
              <AutoAwesomeOutlined sx={{ fontSize: 20, color: t.accent }} />
              <Typography sx={{ fontFamily: "'Manrope', sans-serif", fontWeight: 700, fontSize: 16, color: t.text }}>
                AI Usage This Month
              </Typography>
            </Box>
            {resetsAt && (
              <Typography sx={{ fontSize: 11, color: t.textMuted }}>
                Resets {formatDate(resetsAt)}
              </Typography>
            )}
          </Box>
          <Box sx={{ mt: 2 }}>
            <Box sx={{ height: 8, borderRadius: 8, background: t.cardNested, overflow: 'hidden', mb: 1.5 }}>
              <Box
                sx={{
                  width: `${pct * 100}%`,
                  height: '100%',
                  borderRadius: 8,
                  background: pct > 0.8 ? t.warning : t.accent,
                  transition: 'width 400ms ease',
                }}
              />
            </Box>
            <Box sx={{ display: 'flex', justifyContent: 'space-between' }}>
              {hasUsageData ? (
                <>
                  <Typography sx={{ fontSize: 13, color: t.textSub }}>
                    {used} / {limit} credits used
                  </Typography>
                  <Typography sx={{ fontSize: 13, fontWeight: 700, color: pct > 0.8 ? t.warning : t.accent }}>
                    {Math.round(pct * 100)}%
                  </Typography>
                </>
              ) : (
                <Typography sx={{ fontSize: 13, color: t.textMuted }}>
                  Usage data unavailable
                </Typography>
              )}
            </Box>
          </Box>
        </Box>
      </V2Reveal>
    );
  };

  // Section 3: Plan Comparison
  const renderPlanComparison = () => (
    <V2Reveal delay={160}>
      <Box ref={planComparisonRef}>
        <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', mb: 2.5 }}>
          <Typography sx={{ fontFamily: "'Manrope', sans-serif", fontWeight: 700, fontSize: 18, color: t.text }}>
            Compare Plans
          </Typography>
          <Box sx={{ display: 'flex', gap: 0.5, background: t.cardNested, borderRadius: '10px', p: 0.5 }}>
            <Box
              component="button"
              onClick={() => setBillingInterval('monthly')}
              sx={{
                px: 1.5,
                py: 0.5,
                borderRadius: '8px',
                fontSize: 12,
                fontWeight: 600,
                background: billingInterval === 'monthly' ? t.accent : 'transparent',
                color: billingInterval === 'monthly' ? '#fff' : t.textSub,
                border: 'none',
                cursor: 'pointer',
                transition: 'all 0.18s ease',
              }}
            >
              Monthly
            </Box>
            <Box
              component="button"
              onClick={() => setBillingInterval('annual')}
              sx={{
                px: 1.5,
                py: 0.5,
                borderRadius: '8px',
                fontSize: 12,
                fontWeight: 600,
                background: billingInterval === 'annual' ? t.accent : 'transparent',
                color: billingInterval === 'annual' ? '#fff' : t.textSub,
                border: 'none',
                cursor: 'pointer',
                transition: 'all 0.18s ease',
              }}
            >
              Annual
            </Box>
          </Box>
        </Box>

        <Box
          sx={{
            background: t.warnLow.bg,
            border: `1px solid ${t.warnLow.border}`,
            borderRadius: '12px',
            p: '14px 16px',
            mb: 2.5,
          }}
        >
          <Typography sx={{ fontSize: 12, color: t.warnLow.text, fontWeight: 500 }}>
            Current usage: {planInfo?.portfolios_count || 0} portfolios, {planInfo?.linked_accounts_count || 0} brokerages
            {planInfo?.usage?.ai_narratives && `, ${planInfo.usage.ai_narratives.used} AI insights this month`}
          </Typography>
        </Box>

        <Box sx={{ display: 'grid', gridTemplateColumns: { xs: '1fr', md: 'repeat(3, 1fr)' }, gap: 2 }}>
          {!plans && (
            <Box sx={{ gridColumn: '1 / -1', textAlign: 'center', py: 4 }}>
              {plansError ? (
                <Box component="button" onClick={() => refetchPlans()} sx={{ background: 'none', border: 'none', p: 0, cursor: 'pointer', fontFamily: 'inherit' }}>
                  <Typography sx={{ fontSize: 13, color: t.negative }}>Failed to load plans. <span style={{ textDecoration: 'underline' }}>Retry</span></Typography>
                </Box>
              ) : (
                <Typography sx={{ fontSize: 13, color: t.textMuted }}>Loading plans...</Typography>
              )}
            </Box>
          )}
          {plans?.map((planData) => {
            const isCurrentPlan = planData.plan_id === plan;
            const planPrice = Number(billingInterval === 'monthly' ? planData.price_monthly : planData.price_annual) || 0;
            const planTiers: Record<string, number> = { basic: 0, plus: 1, pro: 2 };
            const currentTier = planTiers[plan] ?? 0;
            const cardTier = planTiers[planData.plan_id] ?? 0;
            const isPopular = planData.plan_id === 'plus';
            const highlightKeys = PLAN_HIGHLIGHT_FEATURES[planData.plan_id] || Object.keys(planData.features || {}).slice(0, 7);

            const isPendingTarget = subscription?.pending_plan_change?.new_plan === planData.plan_id;

            let buttonLabel: string;
            let buttonAction: (() => void) | undefined;
            let buttonDisabled = false;
            if (isPendingTarget) {
              buttonLabel = 'Scheduled';
              buttonDisabled = true;
            } else if (isCurrentPlan && isCancelling) {
              buttonLabel = 'Reactivate';
              buttonAction = () => { if (!reactivateMutation.isPending) reactivateMutation.mutate(); };
            } else if (isCurrentPlan) {
              buttonLabel = 'Current Plan';
              buttonDisabled = true;
            } else if (cardTier > currentTier) {
              buttonLabel = 'Upgrade';
              buttonAction = () => setPlanChangeTarget({ id: planData.plan_id, name: planData.name, direction: 'upgrade' });
            } else {
              buttonLabel = 'Downgrade';
              buttonAction = () => setPlanChangeTarget({ id: planData.plan_id, name: planData.name, direction: 'downgrade' });
            }

            return (
              <Box
                key={planData.plan_id}
                sx={{
                  borderRadius: '14px',
                  background: isCurrentPlan ? t.accentDim : t.card,
                  border: `1px solid ${isCurrentPlan ? t.accentBorder : t.border}`,
                  boxShadow: t.cardShadow,
                  p: '20px',
                  position: 'relative',
                  transition: 'all 160ms ease',
                  '&:hover': { background: isCurrentPlan ? t.accentDim : t.cardElevated, borderColor: t.borderHover, boxShadow: t.hoverShadow, transform: 'translateY(-1px)' },
                }}
              >
                {isPendingTarget && (
                  <Box
                    sx={{
                      position: 'absolute',
                      top: -8,
                      right: 16,
                      px: 1.5,
                      py: 0.5,
                      borderRadius: '6px',
                      background: t.accent,
                      fontSize: 9,
                      fontWeight: 700,
                      color: '#fff',
                      textTransform: 'uppercase',
                      letterSpacing: '0.05em',
                    }}
                  >
                    Scheduled
                  </Box>
                )}
                {isPopular && !isPendingTarget && (
                  <Box
                    sx={{
                      position: 'absolute',
                      top: -8,
                      right: 16,
                      px: 1.5,
                      py: 0.5,
                      borderRadius: '6px',
                      background: t.accent,
                      fontSize: 9,
                      fontWeight: 700,
                      color: '#fff',
                      textTransform: 'uppercase',
                      letterSpacing: '0.05em',
                    }}
                  >
                    Most Popular
                  </Box>
                )}

                <Typography sx={{ fontFamily: "'Manrope', sans-serif", fontWeight: 700, fontSize: 14, color: t.text, mb: 0.5 }}>
                  {planData.name}
                </Typography>
                <Typography sx={{ fontSize: 11, color: t.textMuted, mb: 2 }}>
                  {planData.plan_id === 'basic' ? 'Essential portfolio tracking' : planData.plan_id === 'plus' ? 'Advanced analytics + AI' : 'Unlimited everything + Risk Lab'}
                </Typography>

                <Box sx={{ display: 'flex', alignItems: 'baseline', gap: 0.5, mb: 2.5 }}>
                  <Typography sx={{ fontFamily: "'Manrope', sans-serif", fontWeight: 800, fontSize: 24, color: t.text }}>
                    ${planPrice.toFixed(2)}
                  </Typography>
                  <Typography sx={{ fontSize: 12, color: t.textSub }}>
                    /{billingInterval === 'monthly' ? 'mo' : 'yr'}
                  </Typography>
                </Box>

                <Box sx={{ display: 'flex', flexDirection: 'column', gap: 0.5, mb: 2.5 }}>
                  {highlightKeys.map((key) => {
                    const rawValue = planData.features?.[key];
                    const display = displayFeatureValue(key, rawValue);
                    const included = display !== '—';
                    const label = FEATURE_LABELS[key] || key.replace(/_/g, ' ');
                    const displayText = included && display !== '✓' ? `${label}: ${display}` : label;
                    return (
                      <Box key={key} sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                        <CheckCircleOutline sx={{ fontSize: 14, color: included ? t.accent : t.textMuted, opacity: included ? 1 : 0.3 }} />
                        <Typography sx={{ fontSize: 11, lineHeight: 2, color: included ? t.text : t.textMuted, opacity: included ? 1 : 0.5 }}>
                          {displayText}
                        </Typography>
                      </Box>
                    );
                  })}
                </Box>

                <Box
                  component="button"
                  onClick={buttonAction}
                  disabled={buttonDisabled}
                  sx={{
                    width: '100%',
                    px: 2,
                    py: 1.25,
                    borderRadius: '10px',
                    fontSize: 13,
                    fontWeight: 600,
                    cursor: buttonDisabled ? 'default' : 'pointer',
                    background: buttonDisabled
                      ? 'transparent'
                      : cardTier > currentTier || (isCurrentPlan && isCancelling)
                        ? t.btnGrad
                        : 'transparent',
                    color: buttonDisabled
                      ? t.accent
                      : cardTier > currentTier || (isCurrentPlan && isCancelling)
                        ? '#fff'
                        : t.textMuted,
                    border: buttonDisabled
                      ? `1px solid ${t.accent}`
                      : cardTier > currentTier || (isCurrentPlan && isCancelling)
                        ? 'none'
                        : `1px solid ${t.borderSubtle}`,
                    boxShadow: (!buttonDisabled && (cardTier > currentTier || (isCurrentPlan && isCancelling))) ? t.btnShadow : 'none',
                    transition: 'all 0.18s ease',
                    '&:hover': {
                      background: buttonDisabled
                        ? 'transparent'
                        : cardTier > currentTier || (isCurrentPlan && isCancelling)
                          ? t.accent
                          : t.cardNested,
                    },
                  }}
                >
                  {buttonLabel}
                </Box>
              </Box>
            );
          })}
        </Box>
      </Box>
    </V2Reveal>
  );

  // Section 4: Invoice History
  const renderInvoiceHistory = () => (
    <V2Reveal delay={240}>
      <Box
        sx={{
          borderRadius: '14px',
          background: t.card,
          border: `1px solid ${t.border}`,
          boxShadow: t.cardShadow, transition: 'all 160ms ease', '&:hover': { background: t.cardElevated, borderColor: t.borderHover, boxShadow: t.hoverShadow, transform: 'translateY(-1px)' },
          overflow: 'hidden',
        }}
      >
        <Box sx={{ p: '20px', borderBottom: `1px solid ${t.borderSubtle}` }}>
          <Typography sx={{ fontFamily: "'Manrope', sans-serif", fontWeight: 700, fontSize: 16, color: t.text }}>
            Invoice History
          </Typography>
          <Typography sx={{ fontSize: 11, color: t.textMuted, mt: 0.25 }}>
            Recent billing statements
          </Typography>
        </Box>
        <Box>
          {invoices && invoices.length > 0 ? (
            <Box>
              <Box
                sx={{
                  display: 'grid',
                  gridTemplateColumns: { xs: '1fr', sm: '1fr 1fr 1fr auto' },
                  gap: 2,
                  p: '12px 20px',
                  background: t.cardNested,
                  borderBottom: `1px solid ${t.borderSubtle}`,
                }}
              >
                <Typography sx={{ fontSize: 10, color: t.textMuted, textTransform: 'uppercase', fontWeight: 700 }}>
                  Invoice ID
                </Typography>
                <Typography sx={{ fontSize: 10, color: t.textMuted, textTransform: 'uppercase', fontWeight: 700 }}>
                  Date
                </Typography>
                <Typography sx={{ fontSize: 10, color: t.textMuted, textTransform: 'uppercase', fontWeight: 700 }}>
                  Amount
                </Typography>
                <Typography sx={{ fontSize: 10, color: t.textMuted, textTransform: 'uppercase', fontWeight: 700 }}>
                  Status
                </Typography>
              </Box>
              {invoices.map((invoice, idx) => (
                <Box
                  key={invoice.id}
                  sx={{
                    display: 'grid',
                    gridTemplateColumns: { xs: '1fr', sm: '1fr 1fr 1fr auto' },
                    gap: 2,
                    p: '16px 20px',
                    borderBottom: idx < invoices.length - 1 ? `1px solid ${t.borderSubtle}` : 'none',
                    alignItems: 'center',
                    transition: 'background 0.18s ease',
                    '&:hover': { background: t.cardNested },
                  }}
                >
                  <Typography sx={{ fontSize: 12, fontWeight: 600, color: t.text, fontFamily: "'JetBrains Mono', monospace" }}>
                    {invoice.id}
                  </Typography>
                  <Typography sx={{ fontSize: 12, color: t.textSub }}>
                    {formatDate(invoice.paid_at || invoice.created_at)}
                  </Typography>
                  <Typography sx={{ fontSize: 12, fontWeight: 600, color: t.text, fontFamily: "'JetBrains Mono', monospace" }}>
                    {formatCurrency(invoice.amount_paid)}
                  </Typography>
                  <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, justifyContent: 'flex-end' }}>
                    <V2StatusBadge
                      t={t}
                      severity={invoice.status === 'paid' ? 'positive' : invoice.status === 'pending' ? 'medium' : 'high'}
                      label={capitalizeFirst(invoice.status)}
                    />
                    {invoice.invoice_url && (
                      <Box
                        component="a"
                        href={invoice.invoice_url}
                        target="_blank"
                        rel="noopener noreferrer"
                        sx={{
                          display: 'flex',
                          alignItems: 'center',
                          justifyContent: 'center',
                          width: 28,
                          height: 28,
                          borderRadius: '6px',
                          background: 'transparent',
                          border: `1px solid ${t.borderSubtle}`,
                          color: t.textMuted,
                          cursor: 'pointer',
                          transition: 'all 0.18s ease',
                          '&:hover': { background: t.accentDim, borderColor: t.accentBorder, color: t.accent },
                        }}
                      >
                        <DownloadOutlined sx={{ fontSize: 14 }} />
                      </Box>
                    )}
                  </Box>
                </Box>
              ))}
            </Box>
          ) : (
            <Typography sx={{ fontSize: 13, color: t.textMuted, textAlign: 'center', py: 4 }}>
              No invoices available
            </Typography>
          )}
        </Box>
      </Box>
    </V2Reveal>
  );

  const handleConfirmCancel = () => {
    cancelMutation.mutate({ immediate: false }, {
      onSuccess: () => {
        setCancelDialogOpen(false);
        setCancelSuccess(true);
        setTimeout(() => setCancelSuccess(false), 5000);
      },
    });
  };

  const handleConfirmPlanChange = () => {
    if (!planChangeTarget) return;
    const interval = subscription?.billing_interval === 'year' ? 'year' : 'month';
    changePlanMutation.mutate(
      { plan_id: planChangeTarget.id, billing_interval: interval },
      {
        onSuccess: () => {
          const msg = planChangeTarget.direction === 'upgrade'
            ? `Successfully upgraded to ${planChangeTarget.name}!`
            : `Downgrade to ${planChangeTarget.name} scheduled — takes effect at the end of your billing period.`;
          setPlanChangeTarget(null);
          changePlanMutation.reset();
          setPlanChangeSuccess(msg);
          setTimeout(() => setPlanChangeSuccess(null), 8000);
        },
      },
    );
  };

  const renewalDate = subscription?.next_invoice_date
    ? formatDate(subscription.next_invoice_date)
    : 'the end of your current billing period';

  return (
    <Box sx={{ display: 'flex', flexDirection: 'column', gap: 3 }}>
      {cancelSuccess && (
        <Box sx={{ p: 2, borderRadius: '12px', background: t.accentDim, border: `1px solid ${t.accentBorder}` }}>
          <Typography sx={{ fontSize: 13, color: t.accent, fontWeight: 500 }}>
            Your subscription has been cancelled. You will retain access until {renewalDate}.
          </Typography>
        </Box>
      )}
      {planChangeSuccess && (
        <Box sx={{ p: 2, borderRadius: '12px', background: t.accentDim, border: `1px solid ${t.accentBorder}` }}>
          <Typography sx={{ fontSize: 13, color: t.accent, fontWeight: 500 }}>
            {planChangeSuccess}
          </Typography>
        </Box>
      )}
      {renderHeroSection()}
      {renderPlanComparison()}
      {renderInvoiceHistory()}

      <Dialog
        open={cancelDialogOpen}
        onClose={() => setCancelDialogOpen(false)}
        PaperProps={{
          sx: {
            background: t.card,
            border: `1px solid ${t.border}`,
            borderRadius: '20px',
            maxWidth: 440,
            boxShadow: t.shadow,
            p: 1,
          },
        }}
      >
        <DialogTitle sx={{ display: 'flex', alignItems: 'flex-start', gap: 1.5, pb: 1.5 }}>
          <Box
            sx={{
              width: 32,
              height: 32,
              borderRadius: '9px',
              background: `${t.negative}14`,
              border: `1px solid ${t.negative}28`,
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              flexShrink: 0,
            }}
          >
            <WarningAmberOutlined sx={{ color: t.negative, fontSize: 18 }} />
          </Box>
          <Box sx={{ flex: 1 }}>
            <Typography sx={{ fontFamily: "'Manrope', sans-serif", fontWeight: 700, fontSize: 16, color: t.text }}>
              Cancel Subscription
            </Typography>
          </Box>
          <Box
            component="button"
            onClick={() => setCancelDialogOpen(false)}
            sx={{
              background: 'transparent',
              border: 'none',
              color: t.textMuted,
              cursor: 'pointer',
              p: 0.5,
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              '&:hover': { color: t.text },
            }}
          >
            ✕
          </Box>
        </DialogTitle>
        <DialogContent sx={{ px: 3, pb: 2 }}>
          {cancelMutation.isError && (
            <Box sx={{ mb: 2, p: 1.5, borderRadius: '8px', background: `${t.negative}10`, border: `1px solid ${t.negative}30` }}>
              <Typography sx={{ fontSize: 12, color: t.negative, fontWeight: 500 }}>
                {(cancelMutation.error as { response?: { data?: { error?: string } } })?.response?.data?.error || 'Failed to cancel subscription. Please try again.'}
              </Typography>
            </Box>
          )}
          <Typography sx={{ fontSize: 13, color: t.textSub, lineHeight: 1.7, mb: 2 }}>
            Your subscription will remain active until <strong style={{ color: t.text }}>{renewalDate}</strong>. After that date:
          </Typography>
          <Box component="ul" sx={{ pl: 2.5, m: 0, '& li': { fontSize: 12, color: t.textSub, mb: 1, lineHeight: 1.5 } }}>
            <li>You will lose access to premium features (AI insights, Risk Lab, advanced analytics)</li>
            <li>Portfolio data will be preserved but read-only</li>
            <li>Connected brokerage accounts will stop syncing</li>
            <li>You can reactivate at any time before the period ends</li>
          </Box>
          <Box sx={{ mt: 2.5, p: 2, borderRadius: '10px', background: `${t.negative}06`, border: `1px solid ${t.negative}15` }}>
            <Typography sx={{ fontSize: 12, color: t.textSub, fontWeight: 500, lineHeight: 1.6 }}>
              This action cannot be undone after the billing period expires.
            </Typography>
          </Box>
        </DialogContent>
        <DialogActions sx={{ px: 3, pb: 2.5, gap: 1 }}>
          <Button
            onClick={() => setCancelDialogOpen(false)}
            variant="contained"
            sx={{
              borderRadius: '10px',
              textTransform: 'none',
              fontSize: 13,
              fontWeight: 600,
              background: t.btnGrad,
              color: '#fff',
              boxShadow: 'none',
              '&:hover': { opacity: 0.9, boxShadow: t.btnShadow },
            }}
          >
            Keep my plan
          </Button>
          <Button
            onClick={handleConfirmCancel}
            disabled={cancelMutation.isPending}
            sx={{
              borderRadius: '10px',
              textTransform: 'none',
              fontSize: 13,
              fontWeight: 600,
              background: 'transparent',
              border: `1px solid ${t.accent}`,
              color: t.accent,
              '&:hover': { background: `${t.accent}08` },
              '&.Mui-disabled': { opacity: 0.5, color: t.accent, border: `1px solid ${t.accent}` },
            }}
          >
            {cancelMutation.isPending ? 'Cancelling...' : 'Confirm cancellation'}
          </Button>
        </DialogActions>
      </Dialog>

      <PaymentMethodUpdateDialog
        open={paymentDialogOpen}
        onClose={() => setPaymentDialogOpen(false)}
      />

      <Dialog
        open={!!planChangeTarget}
        onClose={() => { setPlanChangeTarget(null); changePlanMutation.reset(); }}
        PaperProps={{
          sx: {
            background: t.card,
            border: `1px solid ${t.border}`,
            borderRadius: '16px',
            maxWidth: 440,
            p: 1,
          },
        }}
      >
        <DialogTitle sx={{ display: 'flex', alignItems: 'center', gap: 1.5, color: t.text, fontFamily: "'Manrope', sans-serif", fontWeight: 700, fontSize: 18 }}>
          <WarningAmberOutlined sx={{ color: t.accent, fontSize: 22 }} />
          {planChangeTarget?.direction === 'downgrade' ? 'Downgrade Plan' : 'Upgrade Plan'}
        </DialogTitle>
        <DialogContent>
          {changePlanMutation.isError && (
            <Box sx={{ mb: 2, p: 1.5, borderRadius: '8px', background: `${t.negative}10`, border: `1px solid ${t.negative}30` }}>
              <Typography sx={{ fontSize: 12, color: t.negative, fontWeight: 500 }}>
                {(changePlanMutation.error as { response?: { data?: { error?: string } } })?.response?.data?.error || 'Plan change failed. Please try again.'}
              </Typography>
            </Box>
          )}
          {planChangeTarget?.direction === 'downgrade' ? (
            <>
              <Typography sx={{ fontSize: 13, color: t.textSub, lineHeight: 1.7, mb: 2 }}>
                You are about to downgrade from <strong style={{ color: t.text }}>{(currentPlan?.name || planName)}</strong> to <strong style={{ color: t.text }}>{planChangeTarget.name}</strong>. This change takes effect at the end of your current billing period.
              </Typography>
              <Box component="ul" sx={{ pl: 2.5, m: 0, '& li': { fontSize: 12, color: t.textSub, mb: 1, lineHeight: 1.5 } }}>
                <li>You may lose access to features not included in the {planChangeTarget.name} plan</li>
                <li>Portfolio data will be preserved</li>
                <li>You can upgrade again at any time</li>
              </Box>
            </>
          ) : (
            <Typography sx={{ fontSize: 13, color: t.textSub, lineHeight: 1.7 }}>
              You are about to upgrade from <strong style={{ color: t.text }}>{(currentPlan?.name || planName)}</strong> to <strong style={{ color: t.text }}>{planChangeTarget?.name}</strong>. The price difference will be prorated for the remainder of your billing cycle.
            </Typography>
          )}
        </DialogContent>
        <DialogActions sx={{ px: 3, pb: 2.5, gap: 1 }}>
          <Button
            onClick={() => { setPlanChangeTarget(null); changePlanMutation.reset(); }}
            sx={{ borderRadius: '10px', textTransform: 'none', color: t.textSub, fontSize: 13 }}
          >
            Cancel
          </Button>
          <Button
            onClick={handleConfirmPlanChange}
            disabled={changePlanMutation.isPending}
            variant="contained"
            sx={{
              borderRadius: '10px',
              textTransform: 'none',
              fontSize: 13,
              fontWeight: 600,
              background: t.accent,
              color: '#fff',
              '&:hover': {
                opacity: 0.9,
              },
            }}
          >
            {changePlanMutation.isPending
              ? 'Processing...'
              : planChangeTarget?.direction === 'downgrade'
                ? 'Confirm Downgrade'
                : 'Confirm Upgrade'}
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
}

