import { ReactNode } from 'react';
import { Box, Typography } from '@mui/material';
import { AlertTriangle, AlertCircle, CheckCircle2, Info } from 'lucide-react';
import { V2Tokens } from './tokens';

/**
 * SK4 / C6 (RUS-5795 frozen contract, Arbiter ruling R4): the STATIC
 * severity callout. It absorbs the role of `V2WarningCard` and
 * `V2HeroCallout` (both stay exported until the page migrations finish).
 *
 * `V2StatusStrip` is deliberately a separate primitive — it is collapsible
 * and renders a key/value detail grid. A static note and a collapsing strip
 * have different state models and are NOT merged under variant flags.
 */

export type V2CalloutSeverity = 'high' | 'medium' | 'low' | 'info' | 'positive' | 'accent';

interface V2CalloutProps {
  t: V2Tokens;
  /** Explicit severity — the callout never infers it from content. */
  severity: V2CalloutSeverity;
  title: string;
  detail?: string;
  /** RUS-5832: rich body slot for metric-rich callouts — rendered in the
   *  content column under `detail` (order: title → detail → body → action).
   *  This is what lets surfaces like the Holdings data-quality panel (inline
   *  metric row + explanation) be Kit-composed instead of page-owned. */
  body?: ReactNode;
  /** Optional icon override; defaults to the severity's standard glyph. */
  icon?: ReactNode;
  /** Caller-owned action slot (ReactNode — canonical controls arrive via RUS-5797). */
  action?: ReactNode;
}

interface CalloutConfig {
  bg: string;
  border: string;
  text: string;
  badge: string;
  Icon: typeof Info;
}

function getCalloutConfig(t: V2Tokens, severity: V2CalloutSeverity): CalloutConfig {
  switch (severity) {
    case 'high': return { ...t.warnHigh, Icon: AlertTriangle };
    case 'medium': return { ...t.warnMed, Icon: AlertCircle };
    // warn.low hue is pending K3 (Tailwind-blue conflict) — the ROLE is frozen,
    // K3 supplies the final hue through the existing token.
    case 'low': return { ...t.warnLow, Icon: Info };
    case 'positive': return { bg: `${t.positive}08`, border: `${t.positive}25`, text: t.positive, badge: `${t.positive}14`, Icon: CheckCircle2 };
    case 'accent': return { bg: t.accentDim, border: t.accentBorder, text: t.accent, badge: t.accentDim, Icon: Info };
    case 'info':
    default: return { bg: `${t.textMuted}08`, border: `${t.textMuted}25`, text: t.textMuted, badge: `${t.textMuted}14`, Icon: Info };
  }
}

export function V2Callout({ t, severity, title, detail, body, icon, action }: V2CalloutProps) {
  const { bg, border, text: sevText, badge, Icon } = getCalloutConfig(t, severity);

  return (
    <Box
      sx={{
        borderRadius: `${t.radius.card}px`,
        background: bg,
        border: `1px solid ${border}`,
        p: `${t.space[16]}px`,
        display: 'flex',
        gap: `${t.space[12]}px`,
      }}
    >
      <Box
        aria-hidden
        sx={{
          width: 28,
          height: 28,
          borderRadius: `${t.radius.control}px`,
          background: badge,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          flexShrink: 0,
          mt: '2px',
        }}
      >
        {icon ?? <Icon size={13} color={sevText} />}
      </Box>
      <Box sx={{ flex: 1, minWidth: 0 }}>
        <Typography sx={{ fontSize: 13, fontWeight: 600, color: t.text }}>{title}</Typography>
        {detail && (
          <Typography sx={{ fontSize: 12, color: t.textSub, lineHeight: 1.5, mt: '4px' }}>{detail}</Typography>
        )}
        {body && <Box sx={{ mt: `${t.space[8]}px` }}>{body}</Box>}
        {action && <Box sx={{ mt: `${t.space[8]}px` }}>{action}</Box>}
      </Box>
    </Box>
  );
}

import { ReactNode } from 'react';
import { Box, Typography } from '@mui/material';
import { V2Tokens } from './tokens';

/**
 * SK4 / C3 (RUS-5795 frozen contract, K7): a 4px meter bar.
 *
 * NEW primitive — the dead `V2ProgressBar` (0 consumers) was a starting
 * reference only; its page-specific threshold colouring (`A5`) is
 * deliberately NOT inherited. The caller owns the value, the range, the
 * semantic tone and the interpretation: this component never infers
 * "good/bad" from the numeric direction.
 */

interface V2MeterBarProps {
  t: V2Tokens;
  /** Caller-owned value. No meaning is derived from it here. */
  score: number;
  /** Caller-owned range maximum — required so no default range is invented. */
  maxScore: number;
  /**
   * RUS-5800 rev 8 (additive): `ReactNode` labels let callers compose a
   * leading adornment (e.g. a country flag beside a geographic-allocation
   * name) without forking the meter. String labels behave exactly as before.
   */
  label?: ReactNode;
  showValue?: boolean;
  /**
   * Exact value string to display. The Kit never formats values — when
   * omitted, the raw score is rendered as-is. Callers pass a preformatted
   * string (e.g. `'—'` for missing, `'72%'`, `'7.2'`) to stay truthful.
   */
  valueLabel?: string;
  /** Caller-supplied fill colour (token-derived). Default `t.accent` (neutral). */
  tone?: string;
  /**
   * Optional marker position within [0, maxScore] — the K7-inferred
   * "score bar with marker" pattern (component-map). Presentation only.
   */
  marker?: number;
}

/**
 * Percentage fill for a value within [0, maxScore]. Non-finite values
 * (NaN/±Infinity) and non-positive ranges clamp to 0 so garbage input can
 * never render a full-width fill; the CALLER decides how to flag bad data.
 */
const clampPct = (value: number, maxScore: number) => {
  if (!Number.isFinite(value) || !Number.isFinite(maxScore) || maxScore <= 0) return 0;
  return Math.min(Math.max(value / maxScore, 0), 1) * 100;
};

/**
 * ONE validated model drives BOTH the presentation and the accessibility
 * attributes (PR #1129 review, revision 2): a meter only exists when the
 * value/range pair is a finite, sensibly-ranged measurement. For invalid
 * input (score or maxScore non-finite, maxScore <= 0) there is no valid
 * measurement to report, so the element renders as a non-semantic decorative
 * bar — NO meter role, NO aria-value* — rather than exposing sanitized-but-
 * fabricated numbers through ARIA. When valid, `aria-valuenow` is clamped to
 * the SAME [0, maxScore] window the visual fill uses, so accessibility and
 * presentation can never disagree (e.g. score 150 of 100 reads as a full
 * meter, not valuenow > valuemax).
 */
export function V2MeterBar({ t, score, maxScore, label, showValue, valueLabel, tone = t.accent, marker }: V2MeterBarProps) {
  const valid = Number.isFinite(score) && Number.isFinite(maxScore) && maxScore > 0;
  const pct = clampPct(score, maxScore);

  const meterAria = valid
    ? {
        role: 'meter',
        'aria-valuenow': Math.min(Math.max(score, 0), maxScore),
        'aria-valuemin': 0,
        'aria-valuemax': maxScore,
        // Rev 8: string labels name the meter; ReactNode adornments carry
        // their own accessible text (e.g. CountryLabel's aria-label).
        'aria-label': typeof label === 'string' ? label : undefined,
      }
    : {};

  const track = (
    <Box
      {...meterAria}
      sx={{
        position: 'relative',
        flex: 1,
        height: '4px',
        borderRadius: `${t.radius.bar}px`,
        background: t.cardNested,
        overflow: marker === undefined ? 'hidden' : 'visible',
      }}
    >
      <Box
        sx={{
          width: `${pct}%`,
          height: '100%',
          borderRadius: `${t.radius.bar}px`,
          background: tone,
          transition: 'width 400ms ease',
        }}
      />
      {marker !== undefined && (
        <Box
          aria-hidden
          sx={{
            position: 'absolute',
            top: '-2px',
            left: `calc(${clampPct(marker, maxScore)}% - 1px)`,
            width: '2px',
            height: '8px',
            borderRadius: `${t.radius.bar}px`,
            background: t.textMuted,
          }}
        />
      )}
    </Box>
  );

  if (label || showValue) {
    return (
      <Box sx={{ display: 'flex', alignItems: 'center', gap: `${t.space[8]}px` }}>
        {label && (
        // Rev 8: string labels keep the kit Typography treatment; ReactNode
        // labels (composed adornments, e.g. country flags) render inside a
        // Box carrying the same truncation constraints.
          typeof label === 'string' ? (
            <Typography sx={{ fontSize: 11, color: t.textSub, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
              {label}
            </Typography>
          ) : (
            <Box sx={{ fontSize: 11, color: t.textSub, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis', flexShrink: 0 }}>
              {label}
            </Box>
          )
        )}
        {track}
        {showValue && (
          <Typography
            sx={{
              fontSize: 11,
              fontWeight: 600,
              fontFeatureSettings: "'tnum' 1",
              color: t.textSub,
              minWidth: 26,
              textAlign: 'right',
            }}
          >
            {valueLabel ?? String(score)}
          </Typography>
        )}
      </Box>
    );
  }

  return <Box sx={{ display: 'flex' }}>{track}</Box>;
}

