import { useRef } from 'react';
import { Box, Typography } from '@mui/material';
import { V2Tokens } from './tokens';

interface V2SegmentedControlProps {
  t: V2Tokens;
  items: { id: string; label: string; disabled?: boolean; description?: string }[];
  active: string;
  onChange: (id: string) => void;
  /** Accessible name for the group (WCAG: a radiogroup must be named).
   *  RUS-5342 (UX-7) — REQUIRED by the type system so no consumer can render
   *  an unnamed radiogroup (review Major #1); e.g. "Analysis interval" on the
   *  Performance page. */
  groupLabel: string;
}

// Mutually exclusive mode/option selector (time periods, risk levels, indicator types)
// NOT for page sections (use V2Tabs) or multi-select filters (use V2FilterChips)
//
// RUS-5342 (UX-7): radiogroup semantics — the container is role="radiogroup",
// each option role="radio" + aria-checked, with the WAI-ARIA keyboard pattern
// (roving tabindex: only the checked option is tabbable; arrow keys move AND
// select the next enabled option, wrapping, skipping disabled ones; Home/End
// jump to the first/last enabled option — review Minor #6).
export function V2SegmentedControl({ t, items, active, onChange, groupLabel }: V2SegmentedControlProps) {
  const optionRefs = useRef<(HTMLElement | null)[]>([]);

  const enabledNeighbor = (from: number, dir: 1 | -1): number => {
    for (let step = 1; step <= items.length; step++) {
      const next = (from + dir * step + items.length * 2) % items.length;
      if (!items[next].disabled) return next;
    }
    return from;
  };

  const firstEnabled = (): number => {
    const first = items.findIndex((item) => !item.disabled);
    return first >= 0 ? first : 0;
  };

  const lastEnabled = (): number => {
    for (let i = items.length - 1; i >= 0; i--) {
      if (!items[i].disabled) return i;
    }
    return 0;
  };

  const select = (next: number) => {
    onChange(items[next].id);
    // Roving focus follows the selection (native radiogroup behavior).
    optionRefs.current[next]?.focus();
  };

  const handleKeyDown = (event: React.KeyboardEvent, index: number) => {
    if (
      event.key !== 'ArrowRight' &&
      event.key !== 'ArrowDown' &&
      event.key !== 'ArrowLeft' &&
      event.key !== 'ArrowUp' &&
      event.key !== 'Home' &&
      event.key !== 'End'
    ) {
      return;
    }
    event.preventDefault();
    if (event.key === 'Home') {
      select(firstEnabled());
      return;
    }
    if (event.key === 'End') {
      select(lastEnabled());
      return;
    }
    const dir = event.key === 'ArrowRight' || event.key === 'ArrowDown' ? 1 : -1;
    select(enabledNeighbor(index, dir));
  };

  // Review round 2 P1: a DISABLED active option is not a keyboard stop —
  // disabled buttons cannot receive focus — so tabbability falls back to the
  // first ENABLED option. Only an ENABLED checked option counts as "checked"
  // for that fallback decision (the disabled active radio still keeps its
  // aria-checked state, which is honest: the selection exists but is frozen).
  const hasEnabledChecked = items.some(({ id, disabled }) => id === active && !disabled);

  return (
    <Box role="radiogroup" aria-label={groupLabel} sx={{ display: 'flex', gap: '6px', flexWrap: 'wrap' }}>
      {items.map(({ id, label, disabled, description }, i) => {
        const on = active === id;
        const tabbable = (on && !disabled) || (!hasEnabledChecked && items.findIndex((item) => !item.disabled) === i);
        return (
          <Box
            key={id}
            ref={(el: HTMLElement | null) => {
              optionRefs.current[i] = el;
            }}
            component="button"
            type="button"
            role="radio"
            aria-checked={on}
            tabIndex={tabbable ? 0 : -1}
            disabled={disabled}
            onClick={() => !disabled && onChange(id)}
            onKeyDown={(event) => handleKeyDown(event, i)}
            // RUS-5398 (owner D-9): per-option tooltip — coverage wording
            // only (never "Full analytics"). Surfaced as the native tooltip
            // plus an aria-label carrying the description, so pointer and
            // screen-reader users get the same summary.
            title={description}
            aria-label={description ? `${label} — ${description}` : undefined}
            sx={{
              height: 28,
              px: '12px',
              borderRadius: `${t.radius.control}px`,
              fontSize: 11,
              fontWeight: 600,
              cursor: disabled ? 'not-allowed' : 'pointer',
              opacity: disabled ? 0.35 : 1,
              background: on ? t.accentDim : 'transparent',
              color: on ? t.accent : t.textMuted,
              border: `1px solid ${on ? t.accentBorder : t.border}`,
              transition: 'all 150ms ease',
              display: 'inline-flex',
              alignItems: 'center',
              // Suppress the persistent browser focus ring after pointer clicks
              // while keeping an accessible focus indicator for keyboard users.
              outline: 'none',
              '&:focus': { outline: 'none' },
              '&:focus-visible': disabled ? {} : {
                outline: 'none',
                borderColor: t.accent,
                boxShadow: `0 0 0 2px ${t.accentDim}`,
              },
            }}
          >
            <Typography component="span" sx={{ fontSize: 'inherit', fontWeight: 'inherit', color: 'inherit' }}>
              {label}
            </Typography>
          </Box>
        );
      })}
    </Box>
  );
}

import { ReactNode } from 'react';
import { Box } from '@mui/material';
import { V2Tokens } from './tokens';

export type V2BadgeVariant =
  | 'neutral'
  | 'accent'
  | 'success'
  | 'warning'
  | 'danger'
  | 'info'
  // RUS-5973 (PERF WS-2): the data-provenance trust palette — "this number is
  // modeled, not observed". Mirrors ProvenanceBadge's `simulated` state
  // (`ProvenanceBadge.tsx`, the identical `${t.purple}14 / t.purple /
  // ${t.purple}28` triple) so the two provenance badges on the Performance
  // page cannot diverge. Deliberately NOT the green-teal accent: on these
  // cards green already means a POSITIVE VERDICT, and a modelled-data label
  // must not read as one.
  | 'purple';

interface V2BadgeProps {
  t: V2Tokens;
  label: string;
  variant?: V2BadgeVariant;
  /** B3 `chip` shape (anomaly A4 standardisation): h24 chip with an optional
   *  icon/dot, for icon-bearing classification chips. Colour still comes from
   *  `variant` — chip is anatomy, not a colour. */
  chip?: boolean;
  /** Icon rendered inside a `chip` badge (before the label). */
  icon?: ReactNode;
  /** Render a coloured status dot inside a `chip` badge (before the label). */
  dot?: boolean;
  /**
   * RUS-5860 (additive): SOLID triplet treatment — fills/borders/text from
   * the design file's chip+alert families, as drawn by the Portfolio Risk
   * frame badges (`5362:5954`, `5362:6246`). Default false keeps the frozen
   * alpha treatment for every existing consumer.
   */
  solid?: boolean;
  /**
   * RUS-5800 rev 12 (additive): chip height in px. The frozen B3 default is
   * 24; the recorded Figma DRAWER metadata chips are 28px tall
   * (`5343:3466`, node 5343:3466 block) — drawers pass 28 for that role.
   * Default keeps every existing consumer pixel-identical.
   */
  chipHeight?: number;
}

// B3 (RUS-5795 frozen contract): non-severity status/label pill.
// Visual: dot-pill h20 `radius.pill` (16); `chip` h24; bg `${token}14`,
// border `${token}28`. Badges do NOT infer severity — the caller chooses the
// variant, the badge renders it.
export function V2Badge({ t, label, variant = 'neutral', chip = false, icon, dot, chipHeight, solid }: V2BadgeProps) {
  // Rev 13: an enlarged chip (recorded Figma drawer chips are 28px) scales
  // its label + padding with the height — the compact 24px default is
  // unchanged for every existing consumer.
  const enlarged = chip && (chipHeight ?? 24) > 24;
  const chipFontSize = chip ? (enlarged ? 12 : 11) : 10;
  const chipPx = chip ? (enlarged ? '12px' : '10px') : '8px';
  const colors: Record<V2BadgeVariant, { bg: string; color: string; border: string }> = {
    neutral: { bg: `${t.textMuted}14`, color: t.textSub, border: `${t.textMuted}28` },
    accent: { bg: t.accentDim, color: t.accent, border: t.accentBorder },
    success: { bg: `${t.positive}14`, color: t.positive, border: `${t.positive}28` },
    warning: { bg: `${t.warning}14`, color: t.warning, border: `${t.warning}28` },
    danger: { bg: `${t.negative}14`, color: t.negative, border: `${t.negative}28` },
    info: { bg: `${t.blue}14`, color: t.blue, border: `${t.blue}28` },
    purple: { bg: `${t.purple}14`, color: t.purple, border: `${t.purple}28` },
  };
  // RUS-5860: solid triplets resolve from the chip/alert token families —
  // built lazily so consumers with minimal token fixtures (and every
  // non-solid consumer) never read those groups.
  const c = solid
    ? {
        neutral: { bg: t.cardElevated, color: t.textSub, border: t.border },
        accent: { bg: t.accentDim, color: t.accent, border: t.accentBorder },
        success: { bg: t.chip.successBackground, color: t.chip.successText, border: t.alert.successBorder },
        warning: { bg: t.chip.warningBackground, color: t.chip.warningText, border: t.alert.warningBorder },
        danger: { bg: t.chip.errorBackground, color: t.chip.errorText, border: t.alert.errorBorder },
        info: { bg: t.chip.infoBackground, color: t.chip.infoText, border: t.alert.infoBorder },
      }[variant]
    : colors[variant];

  return (
    <Box
      component="span"
      sx={{
        height: chip ? (chipHeight ?? 24) : 20,
        display: 'inline-flex',
        alignItems: 'center',
        gap: icon ? '4px' : chip ? '4px' : 0,
        px: chipPx,
        borderRadius: `${t.radius.pill}px`,
        fontSize: chipFontSize,
        fontWeight: 650,
        background: c.bg,
        color: c.color,
        border: `1px solid ${c.border}`,
        whiteSpace: 'nowrap',
      }}
    >
      {chip && dot && (
        <Box
          component="span"
          aria-hidden
          sx={{ width: 6, height: 6, borderRadius: '50%', backgroundColor: c.color, flexShrink: 0 }}
        />
      )}
      {/* RUS-5860 R7: icons render on ANY badge shape (solid included) —
          the consolidation onto V2Badge relies on it; the sole pre-existing
          icon consumer already passed `chip`, so its rendering is
          unchanged. Spacing applies whenever an icon is present. */}
      {icon && (
        <Box component="span" sx={{ display: 'inline-flex', alignItems: 'center', flexShrink: 0 }}>
          {icon}
        </Box>
      )}
      {label}
    </Box>
  );
}

