import { useState, ReactNode, CSSProperties } from 'react';
import { Box, Typography } from '@mui/material';
import { V2Tokens, v2Typography } from './tokens';

interface V2SectionCardProps {
  t: V2Tokens;
  title: string;
  subtitle?: string;
  action?: ReactNode;
  /**
   * RUS-5859 remediation (additive, same precedent as V2Badge.chipHeight /
   * V2HeroCard.iconBoxSize): the approved Health frames draw a 40×40
   * accentDim icon well left of the title in every section-card header
   * (evidence: 5105:537 Assessment, 5179:186 Key Strengths, 5107:2572 What
   * Changed, 5107:2636 Score Breakdown, 5436:140xx Risk Contribution — file
   * WI8kDNCd02g1tpjNmMW49X). The glyph is accent-toned on `accentDim`.
   * When omitted, every existing consumer renders pixel-identically.
   */
  icon?: ReactNode;
  children: ReactNode;
  /** Opt IN to the hover bg/border swap (which never lifts or re-shadows,
   *  E7). Default derives from interactivity (PR #1127 review P2, contract
   *  A1 "hoverable stays only for genuinely interactive cards"): cards with
   *  an `onClick` hover; PASSIVE cards do not hover unless explicitly
   *  `hoverable`. */
  hoverable?: boolean;
  onClick?: () => void;
  /**
   * RUS-5846 (additive, same precedent as V2Badge.chipHeight /
   * V2HeroCard.iconBoxSize): layout properties for the card ROOT (stable
   * min-height and grid-stretch height), for callers whose page geometry
   * needs them. Never carries visual styling — surface/border/type stay
   * token-driven above. Default undefined: every existing consumer renders
   * pixel-identically.
   */
  style?: CSSProperties;
  /**
   * RUS-5903 (additive, same precedent as V2Button.testId, RUS-5897):
   * renders `data-testid` on the root for callers whose flows are driven by
   * test ids (the guest-mode contract spec anchors the Accounts page's
   * account cards). Omitted → renders nothing extra.
   */
  testId?: string;
}

export function V2SectionCard({ t, title, subtitle, action, icon, children, hoverable, onClick, style, testId }: V2SectionCardProps) {
  const [hov, setHov] = useState(false);
  const isHover = (hoverable ?? Boolean(onClick)) && hov;

  return (
    <Box
      data-testid={testId}
      onMouseEnter={() => setHov(true)}
      onMouseLeave={() => setHov(false)}
      onClick={onClick}
      style={style}
      sx={{
        borderRadius: `${t.radius.card}px`,
        background: isHover ? t.cardElevated : t.card,
        border: `1px solid ${isHover ? t.borderHover : t.border}`,
        // E7 (RUS-5795): passive cards are border-driven — no lift, no shadow
        // change. `effect.card` is the frozen near-none treatment.
        boxShadow: t.effect.card,
        transition: 'background 160ms ease, border-color 160ms ease',
        cursor: onClick ? 'pointer' : 'default',
        padding: `${t.space[16]}px`,
        overflow: 'visible',
      }}
    >
      {/* 18px header margin (2.25 × theme spacing) is pre-existing density —
          off the frozen space scale (no 18 step); documented, not distorted
          to a neighbouring token (PR #1127 review P2 record fix). The 12px
          subtitle is the frozen A1 contract value. */}
      <Box sx={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', mb: 2.25 }}>
        <Box sx={{ display: 'flex', alignItems: 'center', gap: `${t.space[12]}px`, minWidth: 0 }}>
          {icon && (
            <Box
              aria-hidden
              sx={{
                width: 40,
                height: 40,
                flexShrink: 0,
                borderRadius: `${t.radius.control}px`,
                background: t.accentDim,
                color: t.accent,
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
              }}
            >
              {icon}
            </Box>
          )}
          <Box sx={{ minWidth: 0 }}>
            <Typography sx={{ ...v2Typography.sectionTitle, color: t.text }}>
              {title}
            </Typography>
            {subtitle && (
              <Typography sx={{ fontSize: 12, color: t.textMuted, mt: 0.375 }}>{subtitle}</Typography>
            )}
          </Box>
        </Box>
        {action}
      </Box>
      {children}
    </Box>
  );
}

