import { Box, Typography } from '@mui/material';
import { V2Tokens } from './tokens';

type Severity = 'high' | 'medium' | 'low' | 'info' | 'positive';

interface V2StatusBadgeProps {
  t: V2Tokens;
  severity: Severity;
  label: string;
}

function getSeverityColors(t: V2Tokens, severity: Severity) {
  switch (severity) {
    case 'high': return { bg: t.warnHigh.badge, text: t.warnHigh.text, border: t.warnHigh.border };
    case 'medium': return { bg: t.warnMed.badge, text: t.warnMed.text, border: t.warnMed.border };
    case 'low': return { bg: t.warnLow.badge, text: t.warnLow.text, border: t.warnLow.border };
    case 'positive': return { bg: `${t.positive}14`, text: t.positive, border: `${t.positive}35` };
    case 'info':
    default: return { bg: `${t.textMuted}14`, text: t.textMuted, border: `${t.textMuted}30` };
  }
}

// B4 (RUS-5795 frozen contract): SEVERITY badge. Severity is an explicit
// caller input — the badge never looks at a score and decides it is "high"
// (that mapping stays with the page/domain helper). NOT merged with V2Badge
// (Ruling R9). Visual: `radius.control` (the 7px pre-Kit literal aligned to
// the token), uppercase, no mono (E4).
export function V2StatusBadge({ t, severity, label }: V2StatusBadgeProps) {
  const colors = getSeverityColors(t, severity);
  return (
    <Box
      component="span"
      sx={{
        display: 'inline-flex',
        alignItems: 'center',
        px: 1.125,
        py: 0.375,
        borderRadius: `${t.radius.control}px`,
        background: colors.bg,
        border: `1px solid ${colors.border}`,
      }}
    >
      <Typography
        component="span"
        sx={{
          fontSize: 10,
          fontFamily: "'Manrope', sans-serif",
      fontFeatureSettings: "'tnum' 1",
          fontWeight: 700,
          color: colors.text,
          textTransform: 'uppercase',
        }}
      >
        {label}
      </Typography>
    </Box>
  );
}
